#include "GitsnAsnUtilDef.h"

////////////////////////////////////////////////////////////////////////////////
// GitsnAsnUtil
GitsnAsnUtil *GitsnAsnUtil_new(s32_t dummy, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	GitsnAsnUtil *__internal_ret = (GitsnAsnUtil *)Dz1Calloc(sizeof(GitsnAsnUtil), 1, errp);
	if (__internal_ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(GitsnAsnUtil_delAndSetNull, (void *)&__internal_ret);
		
		__internal_ret->dummy = dummy;
		ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (GitsnAsnUtil_delAndSetNull, (void *)&__internal_ret)
	}
	return __internal_ret;
}

void GitsnAsnUtil_purge(GitsnAsnUtil *p)
{
	if (p == NULL) return;
}

void GitsnAsnUtil_del(GitsnAsnUtil *p)
{
	if (p == NULL) return;
	GitsnAsnUtil_purge(p);
	Dz1Free(p);
}

// GitsnAsnUtil
