		Dz1Thread_tprintf(tab, Dz1T("traction = %s(%d)\n"), Gitsn_TractionControlStatusStr(p->traction), p->traction);
		Dz1Thread_tprintf(tab, Dz1T("abs = %s(%d)\n"), Gitsn_AntiLockBrakeStatusStr(p->abs), p->abs);
		Dz1Thread_tprintf(tab, Dz1T("scs = %s(%d)\n"), Gitsn_StabilityControlStatusStr(p->scs), p->scs);
		Dz1Thread_tprintf(tab, Dz1T("brakeBoost = %s(%d)\n"), Gitsn_BrakeBoostAppliedStr(p->brakeBoost), p->brakeBoost);
		Dz1Thread_tprintf(tab, Dz1T("auxBrakes = %s(%d)\n"), Gitsn_AuxiliaryBrakeStatusStr(p->auxBrakes), p->auxBrakes);
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
