		Dz1Thread_tprintf(tab, Dz1T("transmission = %s(%d)\n"), Gitsn_TransmissionStateStr(p->transmission), p->transmission);
		Dz1Thread_tprintf(tab, Dz1T("speed = ")); Gitsn_Speed_dump(&p->speed, tab); 
		Dz1Thread_tprintf(tab, Dz1T("heading = ")); Gitsn_Heading_dump(&p->heading, tab); 
		Dz1Thread_tprintf(tab, Dz1T("angle = ")); Gitsn_SteeringWheelAngle_dump(&p->angle, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("accelSet = ")); Gitsn_AccelerationSet4Way_dump(p->accelSet, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("brakes = ")); Gitsn_BrakeSystemStatus_dump(p->brakes, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("size = ")); Gitsn_VehicleSize_dump(p->size, tab); 
