////////////////////////////////////////////////////////////////////////////////
// Gitsn_SpeedLimitList
static Dz1Error Gitsn_SpeedLimitList_add(Gitsn_SpeedLimitList *p, Gitsn_RegulatorySpeedLimit *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	err = Dz1Fifo_push(p->storage, data);
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

static Gitsn_RegulatorySpeedLimit *Gitsn_SpeedLimitList_extract(Gitsn_SpeedLimitList *p, Gitsn_RegulatorySpeedLimit *ptr)
{
	return (Gitsn_RegulatorySpeedLimit *)Dz1Fifo_extract(p->storage, ptr);
}

typedef struct Gitsn_SpeedLimitListMkArrArg
{
	Gitsn_RegulatorySpeedLimit **arr;
	unsigned int idx;
} Gitsn_SpeedLimitListMkArrArg;

static Dz1Error _Gitsn_SpeedLimitList_get_array(void *ptr, Gitsn_RegulatorySpeedLimit *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_SpeedLimitListMkArrArg *arg = (Gitsn_SpeedLimitListMkArrArg *)ptr;
	arg->arr[arg->idx++] = p;
	return err;
}

static Gitsn_RegulatorySpeedLimit **Gitsn_SpeedLimitList_get_array(Gitsn_SpeedLimitList *p, unsigned int *ret_cnt, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err == NULL ? &_err : err;
	Gitsn_RegulatorySpeedLimit **ret = NULL;
	unsigned int cnt = 0;
	if (p == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = (Gitsn_RegulatorySpeedLimit **)Dz1Calloc(sizeof(Gitsn_RegulatorySpeedLimit *), (cnt = p->count(p)) + 1, errp)) == NULL) ERR_OUT(errp);
	else
	{
		Gitsn_SpeedLimitListMkArrArg arg = { ret, 0 };
		pthread_cleanup_push(Dz1Memory_cancel, (void *)ret);

		*errp = p->travel(p, _Gitsn_SpeedLimitList_get_array, (void *)&arg);
		if (ERR_PROBE(errp)) ERR_OUT(errp);
		else
		{
			if (ret_cnt) (*ret_cnt) = cnt;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Dz1Memory_cancel, (void *)ret);
	}
	if (ERR_PROBE(errp)) ret = NULL;
	return ret;
}

static Dz1Error Gitsn_SpeedLimitList_travelForward(Gitsn_SpeedLimitList *p, Dz1Error (*func)(void *ptr, Gitsn_RegulatorySpeedLimit *data), void *ptr)
{
	return Dz1Fifo_travelForward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Dz1Error Gitsn_SpeedLimitList_travelBackward(Gitsn_SpeedLimitList *p, Dz1Error (*func)(void *ptr, Gitsn_RegulatorySpeedLimit *data), void *ptr)
{
	return Dz1Fifo_travelBackward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Gitsn_RegulatorySpeedLimit *Gitsn_SpeedLimitList_getHead(Gitsn_SpeedLimitList *p)
{
	return (Gitsn_RegulatorySpeedLimit *)Dz1Fifo_getFirst(p->storage);
}

static unsigned int Gitsn_SpeedLimitList_count(Gitsn_SpeedLimitList *p)
{
	unsigned int ret = Dz1Fifo_count(p->storage);
	return ret;
}

Gitsn_SpeedLimitList *Gitsn_SpeedLimitList_new(Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_SpeedLimitList *ret = (Gitsn_SpeedLimitList *)Dz1Calloc(sizeof(Gitsn_SpeedLimitList), 1, errp);
	if (ret == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_SpeedLimitList_delAndSetNull, (void *)&ret);

		if ((ret->storage = Dz1Fifo_newDynamic(
				(Dz1DelFunc)Gitsn_RegulatorySpeedLimit_del,
				NULL, errp)) == NULL) ERR_OUT(errp);
		else
		{
			ret->count = Gitsn_SpeedLimitList_count;
			ret->travel = Gitsn_SpeedLimitList_travelForward;
			ret->travelForward = Gitsn_SpeedLimitList_travelForward;
			ret->travelBackward = Gitsn_SpeedLimitList_travelBackward;
			ret->get_array = Gitsn_SpeedLimitList_get_array;
			ret->add = Gitsn_SpeedLimitList_add;
			ret->extract = Gitsn_SpeedLimitList_extract;
			ret->getHead = Gitsn_SpeedLimitList_getHead;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_SpeedLimitList_delAndSetNull, (void *)&ret);
	}
	return ret;
}

static Dz1Error _Gitsn_SpeedLimitList_clone(void *ptr, Gitsn_RegulatorySpeedLimit *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_SpeedLimitList *p = (Gitsn_SpeedLimitList *)ptr;
	Gitsn_RegulatorySpeedLimit *cloned = Gitsn_RegulatorySpeedLimit_clone(data, &err); // normal
	err = Dz1Fifo_push(p->storage, cloned); // chk
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

Gitsn_SpeedLimitList *Gitsn_SpeedLimitList_clone(Gitsn_SpeedLimitList *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_SpeedLimitList *ret = NULL;
	if (src == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = Gitsn_SpeedLimitList_new(errp)) == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_SpeedLimitList_delAndSetNull, (void *)&ret);

		*errp = Dz1Fifo_travelForward(src->storage, (Dz1FifoTravelFunc)_Gitsn_SpeedLimitList_clone, (void *)ret);

		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_SpeedLimitList_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_SpeedLimitList_purge(Gitsn_SpeedLimitList *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_empty(p->storage);
}

void Gitsn_SpeedLimitList_del(Gitsn_SpeedLimitList *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_del(p->storage);
	Dz1Free(p);
}

static Dz1Error _Gitsn_SpeedLimitList_dump(void *ptr, Gitsn_RegulatorySpeedLimit *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Dz1ListFDumpArg2 *arg = (Dz1ListFDumpArg2 *)ptr;
	int tab = *(int *)arg->tab;
	Dz1Thread_tprintf(tab, Dz1T("entry = ")); Gitsn_RegulatorySpeedLimit_dump(p, tab);
	return err;
}

void Gitsn_SpeedLimitList_dump(Gitsn_SpeedLimitList *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else
	{
		Dz1ListFDumpArg2 arg = { NULL, &tab };
		Dz1Thread_tprintf(tab, Dz1T("{\n")); tab++;
		p->travel(p, _Gitsn_SpeedLimitList_dump, (void *)&arg);
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
	}
}
