			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneTypeAttributesPresent_sidewalk:
			// _U_prim_clone
			if (ptr != NULL) ret->x.sidewalk = (Gitsn_LaneAttributes_Sidewalk *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneTypeAttributesPresent_median:
			// _U_prim_clone
			if (ptr != NULL) ret->x.median = (Gitsn_LaneAttributes_Barrier *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneTypeAttributesPresent_striping:
			// _U_prim_clone
			if (ptr != NULL) ret->x.striping = (Gitsn_LaneAttributes_Striping *)ptr;
