	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->directionalUse && (dst->directionalUse = Gitsn_LaneDirection_clone(src->directionalUse, errp)) == NULL) ERR_OUT(errp);
	else if (src->sharedWith && (dst->sharedWith = Gitsn_LaneSharing_clone(src->sharedWith, errp)) == NULL) ERR_OUT(errp);
	else if (src->laneType && (dst->laneType = Gitsn_LaneTypeAttributes_clone(src->laneType, errp)) == NULL) ERR_OUT(errp);
