////////////////////////////////////////////////////////////////////////////////
// Gitsn_LaneDataAttribute
Gitsn_LaneDataAttribute *Gitsn_LaneDataAttribute_new(Gitsn_LaneDataAttributePresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_LaneDataAttribute *ret = (Gitsn_LaneDataAttribute *)Dz1Calloc(sizeof(Gitsn_LaneDataAttribute), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_LaneDataAttribute_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_LaneDataAttributePresent_pathEndPointAngle:
			// _U_prim_clone
			if (ptr != NULL) ret->x.pathEndPointAngle = *(Gitsn_DeltaAngle *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_laneCrownPointCenter:
			// _U_prim_clone
			if (ptr != NULL) ret->x.laneCrownPointCenter = *(Gitsn_RoadwayCrownAngle *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_laneCrownPointLeft:
			// _U_prim_clone
			if (ptr != NULL) ret->x.laneCrownPointLeft = *(Gitsn_RoadwayCrownAngle *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_laneCrownPointRight:
			// _U_prim_clone
			if (ptr != NULL) ret->x.laneCrownPointRight = *(Gitsn_RoadwayCrownAngle *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_laneAngle:
			// _U_prim_clone
			if (ptr != NULL) ret->x.laneAngle = *(Gitsn_MergeDivergeNodeAngle *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_speedLimits:
			// _U_cst_clone
			if (ptr != NULL) ret->x.speedLimits = (Gitsn_SpeedLimitList *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_LaneDataAttribute_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_LaneDataAttribute_copy(Gitsn_LaneDataAttribute *ret, Gitsn_LaneDataAttribute *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_LaneDataAttributePresent_pathEndPointAngle:
			// _U_prim_clone
			ret->x.pathEndPointAngle = src->x.pathEndPointAngle;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_laneCrownPointCenter:
			// _U_prim_clone
			ret->x.laneCrownPointCenter = src->x.laneCrownPointCenter;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_laneCrownPointLeft:
			// _U_prim_clone
			ret->x.laneCrownPointLeft = src->x.laneCrownPointLeft;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_laneCrownPointRight:
			// _U_prim_clone
			ret->x.laneCrownPointRight = src->x.laneCrownPointRight;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_laneAngle:
			// _U_prim_clone
			ret->x.laneAngle = src->x.laneAngle;
			ERR_CLEAR(errp);
			break;
		case Gitsn_LaneDataAttributePresent_speedLimits:
			// _U_cst_clone
			if (src->x.speedLimits && (ret->x.speedLimits = Gitsn_SpeedLimitList_clone(src->x.speedLimits, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_LaneDataAttribute *Gitsn_LaneDataAttribute_clone(Gitsn_LaneDataAttribute *src, Dz1Error *err)
{
	Gitsn_LaneDataAttribute *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (Gitsn_LaneDataAttribute *)Dz1Calloc(sizeof(Gitsn_LaneDataAttribute), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_LaneDataAttribute_delAndSetNull, (void *)&ret);
		if (Gitsn_LaneDataAttribute_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_LaneDataAttribute_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_LaneDataAttribute_purge(Gitsn_LaneDataAttribute *p)
{
	if (!p) return;
	switch(p->present)
	{
	case Gitsn_LaneDataAttributePresent_pathEndPointAngle:
		break;
	case Gitsn_LaneDataAttributePresent_laneCrownPointCenter:
		break;
	case Gitsn_LaneDataAttributePresent_laneCrownPointLeft:
		break;
	case Gitsn_LaneDataAttributePresent_laneCrownPointRight:
		break;
	case Gitsn_LaneDataAttributePresent_laneAngle:
		break;
	case Gitsn_LaneDataAttributePresent_speedLimits:
		Gitsn_SpeedLimitList_del(p->x.speedLimits);
		break;
	default:
		break;
	}
}

void Gitsn_LaneDataAttribute_del(Gitsn_LaneDataAttribute *p)
{
	if (!p) return;
	Gitsn_LaneDataAttribute_purge(p);
	Dz1Free(p);
}

void Gitsn_LaneDataAttribute_dump(Gitsn_LaneDataAttribute *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else switch(p->present)
	{
	case Gitsn_LaneDataAttributePresent_pathEndPointAngle:
		Dz1Thread_printf(Dz1T("pathEndPointAngle = ")); Gitsn_DeltaAngle_dump(&p->x.pathEndPointAngle, tab); 
		break;
	case Gitsn_LaneDataAttributePresent_laneCrownPointCenter:
		Dz1Thread_printf(Dz1T("laneCrownPointCenter = ")); Gitsn_RoadwayCrownAngle_dump(&p->x.laneCrownPointCenter, tab); 
		break;
	case Gitsn_LaneDataAttributePresent_laneCrownPointLeft:
		Dz1Thread_printf(Dz1T("laneCrownPointLeft = ")); Gitsn_RoadwayCrownAngle_dump(&p->x.laneCrownPointLeft, tab); 
		break;
	case Gitsn_LaneDataAttributePresent_laneCrownPointRight:
		Dz1Thread_printf(Dz1T("laneCrownPointRight = ")); Gitsn_RoadwayCrownAngle_dump(&p->x.laneCrownPointRight, tab); 
		break;
	case Gitsn_LaneDataAttributePresent_laneAngle:
		Dz1Thread_printf(Dz1T("laneAngle = ")); Gitsn_MergeDivergeNodeAngle_dump(&p->x.laneAngle, tab); 
		break;
	case Gitsn_LaneDataAttributePresent_speedLimits:
		Dz1Thread_printf(Dz1T("speedLimits = ")); Gitsn_SpeedLimitList_dump(p->x.speedLimits, tab); 
		break;
	default:
		Dz1Thread_tprintf(tab, Dz1T("??? = %d\n"), p->present);
		break;
	}
}

