static Dz1Error Gitsn_NodeSetXY_add(Gitsn_NodeSetXY *p, Gitsn_NodeXY *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	err = Dz1Fifo_push(p->storage, data);
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

static Gitsn_NodeXY *Gitsn_NodeSetXY_extract(Gitsn_NodeSetXY *p, Gitsn_NodeXY *ptr)
{
	return (Gitsn_NodeXY *)Dz1Fifo_extract(p->storage, ptr);
}

typedef struct Gitsn_NodeSetXYMkArrArg
{
	Gitsn_NodeXY **arr;
	unsigned int idx;
} Gitsn_NodeSetXYMkArrArg;

static Dz1Error _Gitsn_NodeSetXY_get_array(void *ptr, Gitsn_NodeXY *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_NodeSetXYMkArrArg *arg = (Gitsn_NodeSetXYMkArrArg *)ptr;
	arg->arr[arg->idx++] = p;
	return err;
}

static Gitsn_NodeXY **Gitsn_NodeSetXY_get_array(Gitsn_NodeSetXY *p, unsigned int *ret_cnt, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err == NULL ? &_err : err;
	Gitsn_NodeXY **ret = NULL;
	unsigned int cnt = 0;
	if (p == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = (Gitsn_NodeXY **)Dz1Calloc(sizeof(Gitsn_NodeXY *), (cnt = p->count(p)) + 1, errp)) == NULL) ERR_OUT(errp);
	else
	{
		Gitsn_NodeSetXYMkArrArg arg = { ret, 0 };
		pthread_cleanup_push(Dz1Memory_cancel, (void *)ret);

		*errp = p->travel(p, _Gitsn_NodeSetXY_get_array, (void *)&arg);
		if (ERR_PROBE(errp)) ERR_OUT(errp);
		else
		{
			if (ret_cnt) (*ret_cnt) = cnt;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Dz1Memory_cancel, (void *)ret);
	}
	if (ERR_PROBE(errp)) ret = NULL;
	return ret;
}

static Dz1Error Gitsn_NodeSetXY_travelForward(Gitsn_NodeSetXY *p, Dz1Error (*func)(void *ptr, Gitsn_NodeXY *data), void *ptr)
{
	return Dz1Fifo_travelForward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Dz1Error Gitsn_NodeSetXY_travelBackward(Gitsn_NodeSetXY *p, Dz1Error (*func)(void *ptr, Gitsn_NodeXY *data), void *ptr)
{
	return Dz1Fifo_travelBackward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Gitsn_NodeXY *Gitsn_NodeSetXY_getHead(Gitsn_NodeSetXY *p)
{
	return (Gitsn_NodeXY *)Dz1Fifo_getFirst(p->storage);
}

static unsigned int Gitsn_NodeSetXY_count(Gitsn_NodeSetXY *p)
{
	unsigned int ret = Dz1Fifo_count(p->storage);
	return ret;
}

Gitsn_NodeSetXY *Gitsn_NodeSetXY_new(Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_NodeSetXY *ret = (Gitsn_NodeSetXY *)Dz1Calloc(sizeof(Gitsn_NodeSetXY), 1, errp);
	if (ret == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_NodeSetXY_delAndSetNull, (void *)&ret);

		if ((ret->storage = Dz1Fifo_newDynamic(
				(Dz1DelFunc)Gitsn_NodeXY_del,
				NULL, errp)) == NULL) ERR_OUT(errp);
		else
		{
			ret->count = Gitsn_NodeSetXY_count;
			ret->travel = Gitsn_NodeSetXY_travelForward;
			ret->travelForward = Gitsn_NodeSetXY_travelForward;
			ret->travelBackward = Gitsn_NodeSetXY_travelBackward;
			ret->get_array = Gitsn_NodeSetXY_get_array;
			ret->add = Gitsn_NodeSetXY_add;
			ret->extract = Gitsn_NodeSetXY_extract;
			ret->getHead = Gitsn_NodeSetXY_getHead;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_NodeSetXY_delAndSetNull, (void *)&ret);
	}
	return ret;
}

static Dz1Error _Gitsn_NodeSetXY_clone(void *ptr, Gitsn_NodeXY *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_NodeSetXY *p = (Gitsn_NodeSetXY *)ptr;
	Gitsn_NodeXY *cloned = Gitsn_NodeXY_clone(data, &err); // normal
	err = Dz1Fifo_push(p->storage, cloned); // chk
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

Gitsn_NodeSetXY *Gitsn_NodeSetXY_clone(Gitsn_NodeSetXY *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_NodeSetXY *ret = NULL;
	if (src == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = Gitsn_NodeSetXY_new(errp)) == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_NodeSetXY_delAndSetNull, (void *)&ret);

		*errp = Dz1Fifo_travelForward(src->storage, (Dz1FifoTravelFunc)_Gitsn_NodeSetXY_clone, (void *)ret);

		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_NodeSetXY_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_NodeSetXY_purge(Gitsn_NodeSetXY *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_empty(p->storage);
}

void Gitsn_NodeSetXY_del(Gitsn_NodeSetXY *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_del(p->storage);
	Dz1Free(p);
}

static Dz1Error _Gitsn_NodeSetXY_dump(void *ptr, Gitsn_NodeXY *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Dz1ListFDumpArg2 *arg = (Dz1ListFDumpArg2 *)ptr;
	int tab = *(int *)arg->tab;
	Dz1Thread_tprintf(tab, Dz1T("entry = ")); Gitsn_NodeXY_dump(p, tab);
	return err;
}

