// Gitsn_GenericLane
Gitsn_GenericLane *Gitsn_GenericLane_new(Gitsn_LaneID laneID, 
										 Gitsn_LaneAttributes *laneAttributes, 
										 Gitsn_NodeListXY *nodeList, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_GenericLane *__internal_ret = (Gitsn_GenericLane *)Dz1Calloc(sizeof(Gitsn_GenericLane), 1, errp);
	if (__internal_ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_GenericLane_delAndSetNull, (void *)&__internal_ret);
		
		if ((__internal_ret->connectsTo = Gitsn_ConnectsToList_gen(errp)) == NULL) ERR_OUT(errp);
		else if ((__internal_ret->overlays = Gitsn_OverlayLaneList_gen(errp)) == NULL) ERR_OUT(errp);
		else
		{
			__internal_ret->laneID = laneID;
			__internal_ret->laneAttributes = laneAttributes;
			__internal_ret->nodeList = nodeList;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_GenericLane_delAndSetNull, (void *)&__internal_ret)
	}
	return __internal_ret;
}

bool_t Gitsn_GenericLane_copy(Gitsn_GenericLane *dst, Gitsn_GenericLane *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->name && (dst->name = Gitsn_DescriptiveName_clone(src->name, errp)) == NULL) ERR_OUT(errp);
	else if (src->laneAttributes && (dst->laneAttributes = Gitsn_LaneAttributes_clone(src->laneAttributes, errp)) == NULL) ERR_OUT(errp);
	else if (src->maneuvers && (dst->maneuvers = Gitsn_AllowedManeuvers_clone(src->maneuvers, errp)) == NULL) ERR_OUT(errp);
	else if (src->nodeList && (dst->nodeList = Gitsn_NodeListXY_clone(src->nodeList, errp)) == NULL) ERR_OUT(errp);
	else if (src->connectsTo && (dst->connectsTo = Gitsn_ConnectsToList_clone(src->connectsTo, errp)) == NULL) ERR_OUT(errp);
	else if (src->overlays && (dst->overlays = Gitsn_OverlayLaneList_clone(src->overlays, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->laneID = src->laneID;
		dst->ingressApproach = src->ingressApproach;
		dst->egressApproach = src->egressApproach;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

