Gitsn_DataParameters *Gitsn_DataParameters_new(Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_DataParameters *__internal_ret = (Gitsn_DataParameters *)Dz1Calloc(sizeof(Gitsn_DataParameters), 1, errp);
	if (__internal_ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_DataParameters_delAndSetNull, (void *)&__internal_ret);
		
		ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_DataParameters_delAndSetNull, (void *)&__internal_ret)
	}
	return __internal_ret;
}

bool_t Gitsn_DataParameters_copy(Gitsn_DataParameters *dst, Gitsn_DataParameters *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->processMethod && (dst->processMethod = Dz1Str_clone(src->processMethod, errp)) == NULL) ERR_OUT(errp);
	else if (src->processAgency && (dst->processAgency = Dz1Str_clone(src->processAgency, errp)) == NULL) ERR_OUT(errp);
	else if (src->lastCheckedDate && (dst->lastCheckedDate = Dz1Str_clone(src->lastCheckedDate, errp)) == NULL) ERR_OUT(errp);
	else if (src->geoidUsed && (dst->geoidUsed = Dz1Str_clone(src->geoidUsed, errp)) == NULL) ERR_OUT(errp);
	else
	{
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_DataParameters *Gitsn_DataParameters_clone(Gitsn_DataParameters *src, Dz1Error *err)
{
	Gitsn_DataParameters *dst = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if ((dst = (Gitsn_DataParameters *)Dz1Calloc(sizeof(Gitsn_DataParameters), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_DataParameters_delAndSetNull, (void *)&dst);
		if (Gitsn_DataParameters_copy(dst, src, errp) == FALSE) ERR_SET_OUT(errp, EINVAL);
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_DataParameters_delAndSetNull, (void *)&dst);
	}
	return dst;
}

void Gitsn_DataParameters_purge(Gitsn_DataParameters *p)
{
	if (p == NULL) return;
	Dz1Str_del(p->processMethod);
	Dz1Str_del(p->processAgency);
	Dz1Str_del(p->lastCheckedDate);
	Dz1Str_del(p->geoidUsed);
}

void Gitsn_DataParameters_del(Gitsn_DataParameters *p)
{
	if (p == NULL) return;
	Gitsn_DataParameters_purge(p);
	Dz1Free(p);
}

void Gitsn_DataParameters_dump(Gitsn_DataParameters *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else
	{
		Dz1Thread_printf(Dz1T("{\n")); tab++;
		Dz1Thread_tprintf(tab, Dz1T("processMethod = ")); Dz1Str_dump(p->processMethod, tab); 
		Dz1Thread_tprintf(tab, Dz1T("processAgency = ")); Dz1Str_dump(p->processAgency, tab); 
		Dz1Thread_tprintf(tab, Dz1T("lastCheckedDate = ")); Dz1Str_dump(p->lastCheckedDate, tab); 
		Dz1Thread_tprintf(tab, Dz1T("geoidUsed = ")); Dz1Str_dump(p->geoidUsed, tab); 
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
	}
}
