Gitsn_RestrictionUserType *Gitsn_RestrictionUserType_new(Gitsn_RestrictionUserTypePresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_RestrictionUserType *ret = (Gitsn_RestrictionUserType *)Dz1Calloc(sizeof(Gitsn_RestrictionUserType), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_RestrictionUserType_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_RestrictionUserTypePresent_basicType:
			// _U_enum_clone
			if (ptr != NULL) ret->x.basicType = *(Gitsn_RestrictionAppliesTo *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_RestrictionUserTypePresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_RestrictionUserType_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_RestrictionUserType_copy(Gitsn_RestrictionUserType *ret, Gitsn_RestrictionUserType *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_RestrictionUserTypePresent_basicType:
			// _U_enum_clone
			ret->x.basicType = src->x.basicType;
			ERR_CLEAR(errp);
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_RestrictionUserType *Gitsn_RestrictionUserType_clone(Gitsn_RestrictionUserType *src, Dz1Error *err)
{
	Gitsn_RestrictionUserType *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (Gitsn_RestrictionUserType *)Dz1Calloc(sizeof(Gitsn_RestrictionUserType), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_RestrictionUserType_delAndSetNull, (void *)&ret);
		if (Gitsn_RestrictionUserType_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_RestrictionUserType_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_RestrictionUserType_purge(Gitsn_RestrictionUserType *p)
{
	if (!p) return;
	switch(p->present)
	{
	case Gitsn_RestrictionUserTypePresent_basicType:
		break;
	default:
		break;
	}
}

void Gitsn_RestrictionUserType_del(Gitsn_RestrictionUserType *p)
{
	if (!p) return;
	Gitsn_RestrictionUserType_purge(p);
	Dz1Free(p);
}

void Gitsn_RestrictionUserType_dump(Gitsn_RestrictionUserType *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else switch(p->present)
	{
	case Gitsn_RestrictionUserTypePresent_basicType:
		Dz1Thread_printf(Dz1T("basicType = %s(%d)\n"), Gitsn_RestrictionAppliesToStr(p->x.basicType), p->x.basicType);
		break;
	default:
		Dz1Thread_tprintf(tab, Dz1T("??? = %d\n"), p->present);
		break;
	}
}

