Gitsn_MovementEvent *Gitsn_MovementEvent_new(Gitsn_MovementPhaseState eventState, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_MovementEvent *__internal_ret = (Gitsn_MovementEvent *)Dz1Calloc(sizeof(Gitsn_MovementEvent), 1, errp);
	if (__internal_ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_MovementEvent_delAndSetNull, (void *)&__internal_ret);
		
		if ((__internal_ret->speeds = Gitsn_AdvisorySpeedList_gen(errp)) == NULL) ERR_OUT(errp);
		else
		{
			__internal_ret->eventState = eventState;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_MovementEvent_delAndSetNull, (void *)&__internal_ret)
	}
	return __internal_ret;
}

bool_t Gitsn_MovementEvent_copy(Gitsn_MovementEvent *dst, Gitsn_MovementEvent *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->timing && (dst->timing = Gitsn_TimeChangeDetails_clone(src->timing, errp)) == NULL) ERR_OUT(errp);
	else if (src->speeds && (dst->speeds = Gitsn_AdvisorySpeedList_clone(src->speeds, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->eventState = src->eventState;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_MovementEvent *Gitsn_MovementEvent_clone(Gitsn_MovementEvent *src, Dz1Error *err)
{
	Gitsn_MovementEvent *dst = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if ((dst = (Gitsn_MovementEvent *)Dz1Calloc(sizeof(Gitsn_MovementEvent), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_MovementEvent_delAndSetNull, (void *)&dst);
		if (Gitsn_MovementEvent_copy(dst, src, errp) == FALSE) ERR_SET_OUT(errp, EINVAL);
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_MovementEvent_delAndSetNull, (void *)&dst);
	}
	return dst;
}

void Gitsn_MovementEvent_purge(Gitsn_MovementEvent *p)
{
	if (p == NULL) return;
	Gitsn_TimeChangeDetails_del(p->timing);
	Gitsn_AdvisorySpeedList_del(p->speeds);
}

void Gitsn_MovementEvent_del(Gitsn_MovementEvent *p)
{
	if (p == NULL) return;
	Gitsn_MovementEvent_purge(p);
	Dz1Free(p);
}

void Gitsn_MovementEvent_dump(Gitsn_MovementEvent *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else
	{
		Dz1Thread_printf(Dz1T("{\n")); tab++;
		Dz1Thread_tprintf(tab, Dz1T("eventState = %s(%d)\n"), Gitsn_MovementPhaseStateStr(p->eventState), p->eventState);
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("timing = ")); Gitsn_TimeChangeDetails_dump(p->timing, tab); 
		Dz1Thread_tprintf(tab, Dz1T("speeds = ")); Gitsn_AdvisorySpeedList_dump(p->speeds, tab); 
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
	}
}
