// Gitsn_IntersectionState
Gitsn_IntersectionState *Gitsn_IntersectionState_new(Gitsn_IntersectionReferenceID *id, 
													 Gitsn_MsgCount revision, 
													 Gitsn_IntersectionStatusObject *status, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_IntersectionState *__internal_ret = (Gitsn_IntersectionState *)Dz1Calloc(sizeof(Gitsn_IntersectionState), 1, errp);
	if (__internal_ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_IntersectionState_delAndSetNull, (void *)&__internal_ret);
		
		if ((__internal_ret->enabledLanes = Gitsn_EnabledLaneList_gen(errp)) == NULL) ERR_OUT(errp);
		else if ((__internal_ret->states = Gitsn_MovementList_gen(errp)) == NULL) ERR_OUT(errp);
		else if ((__internal_ret->maneuverAssistList = Gitsn_ManeuverAssistList_gen(errp)) == NULL) ERR_OUT(errp);
		else
		{
			__internal_ret->id = id;
			__internal_ret->revision = revision;
			__internal_ret->status = status;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_IntersectionState_delAndSetNull, (void *)&__internal_ret)
	}
	return __internal_ret;
}

bool_t Gitsn_IntersectionState_copy(Gitsn_IntersectionState *dst, Gitsn_IntersectionState *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->name && (dst->name = Gitsn_DescriptiveName_clone(src->name, errp)) == NULL) ERR_OUT(errp);
	else if (src->id && (dst->id = Gitsn_IntersectionReferenceID_clone(src->id, errp)) == NULL) ERR_OUT(errp);
	else if (src->status && (dst->status = Gitsn_IntersectionStatusObject_clone(src->status, errp)) == NULL) ERR_OUT(errp);
	else if (src->enabledLanes && (dst->enabledLanes = Gitsn_EnabledLaneList_clone(src->enabledLanes, errp)) == NULL) ERR_OUT(errp);
	else if (src->states && (dst->states = Gitsn_MovementList_clone(src->states, errp)) == NULL) ERR_OUT(errp);
	else if (src->maneuverAssistList && (dst->maneuverAssistList = Gitsn_ManeuverAssistList_clone(src->maneuverAssistList, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->revision = src->revision;
		dst->moy = src->moy;
		dst->timeStamp = src->timeStamp;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_IntersectionState *Gitsn_IntersectionState_clone(Gitsn_IntersectionState *src, Dz1Error *err)
{
	Gitsn_IntersectionState *dst = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if ((dst = (Gitsn_IntersectionState *)Dz1Calloc(sizeof(Gitsn_IntersectionState), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_IntersectionState_delAndSetNull, (void *)&dst);
		if (Gitsn_IntersectionState_copy(dst, src, errp) == FALSE) ERR_SET_OUT(errp, EINVAL);
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_IntersectionState_delAndSetNull, (void *)&dst);
	}
	return dst;
}

void Gitsn_IntersectionState_purge(Gitsn_IntersectionState *p)
{
	if (p == NULL) return;
	Gitsn_DescriptiveName_del(p->name);
	Gitsn_IntersectionReferenceID_del(p->id);
	Gitsn_IntersectionStatusObject_del(p->status);
	Gitsn_EnabledLaneList_del(p->enabledLanes);
	Gitsn_MovementList_del(p->states);
	Gitsn_ManeuverAssistList_del(p->maneuverAssistList);
}

void Gitsn_IntersectionState_del(Gitsn_IntersectionState *p)
{
	if (p == NULL) return;
	Gitsn_IntersectionState_purge(p);
	Dz1Free(p);
}

void Gitsn_IntersectionState_dump(Gitsn_IntersectionState *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else
	{
		Dz1Thread_printf(Dz1T("{\n")); tab++;
		Dz1Thread_tprintf(tab, Dz1T("name = ")); Gitsn_DescriptiveName_dump(p->name, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("id = ")); Gitsn_IntersectionReferenceID_dump(p->id, tab); 
		Dz1Thread_tprintf(tab, Dz1T("revision = ")); Gitsn_MsgCount_dump(&p->revision, tab); 
		Dz1Thread_tprintf(tab, Dz1T("status = ")); Gitsn_IntersectionStatusObject_dump(p->status, tab); 
		Dz1Thread_tprintf(tab, Dz1T("moy = ")); Gitsn_MinuteOfTheYear_dump(&p->moy, tab); 
		Dz1Thread_tprintf(tab, Dz1T("timeStamp = ")); Gitsn_DSecond_dump(&p->timeStamp, tab); 
		Dz1Thread_tprintf(tab, Dz1T("enabledLanes = ")); Gitsn_EnabledLaneList_dump(p->enabledLanes, tab); 
		Dz1Thread_tprintf(tab, Dz1T("states = ")); Gitsn_MovementList_dump(p->states, tab); 
		Dz1Thread_tprintf(tab, Dz1T("maneuverAssistList = ")); Gitsn_ManeuverAssistList_dump(p->maneuverAssistList, tab); 
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
	}
}
