static Dz1Error Gitsn_IntersectionStateList_add(Gitsn_IntersectionStateList *p, Gitsn_IntersectionState *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	err = Dz1Fifo_push(p->storage, data);
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

static Gitsn_IntersectionState *Gitsn_IntersectionStateList_extract(Gitsn_IntersectionStateList *p, Gitsn_IntersectionState *ptr)
{
	return (Gitsn_IntersectionState *)Dz1Fifo_extract(p->storage, ptr);
}

typedef struct Gitsn_IntersectionStateListMkArrArg
{
	Gitsn_IntersectionState **arr;
	unsigned int idx;
} Gitsn_IntersectionStateListMkArrArg;

static Dz1Error _Gitsn_IntersectionStateList_get_array(void *ptr, Gitsn_IntersectionState *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_IntersectionStateListMkArrArg *arg = (Gitsn_IntersectionStateListMkArrArg *)ptr;
	arg->arr[arg->idx++] = p;
	return err;
}

static Gitsn_IntersectionState **Gitsn_IntersectionStateList_get_array(Gitsn_IntersectionStateList *p, unsigned int *ret_cnt, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err == NULL ? &_err : err;
	Gitsn_IntersectionState **ret = NULL;
	unsigned int cnt = 0;
	if (p == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = (Gitsn_IntersectionState **)Dz1Calloc(sizeof(Gitsn_IntersectionState *), (cnt = p->count(p)) + 1, errp)) == NULL) ERR_OUT(errp);
	else
	{
		Gitsn_IntersectionStateListMkArrArg arg = { ret, 0 };
		pthread_cleanup_push(Dz1Memory_cancel, (void *)ret);

		*errp = p->travel(p, _Gitsn_IntersectionStateList_get_array, (void *)&arg);
		if (ERR_PROBE(errp)) ERR_OUT(errp);
		else
		{
			if (ret_cnt) (*ret_cnt) = cnt;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Dz1Memory_cancel, (void *)ret);
	}
	if (ERR_PROBE(errp)) ret = NULL;
	return ret;
}

static Dz1Error Gitsn_IntersectionStateList_travelForward(Gitsn_IntersectionStateList *p, Dz1Error (*func)(void *ptr, Gitsn_IntersectionState *data), void *ptr)
{
	return Dz1Fifo_travelForward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Dz1Error Gitsn_IntersectionStateList_travelBackward(Gitsn_IntersectionStateList *p, Dz1Error (*func)(void *ptr, Gitsn_IntersectionState *data), void *ptr)
{
	return Dz1Fifo_travelBackward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Gitsn_IntersectionState *Gitsn_IntersectionStateList_getHead(Gitsn_IntersectionStateList *p)
{
	return (Gitsn_IntersectionState *)Dz1Fifo_getFirst(p->storage);
}

static unsigned int Gitsn_IntersectionStateList_count(Gitsn_IntersectionStateList *p)
{
	unsigned int ret = Dz1Fifo_count(p->storage);
	return ret;
}

Gitsn_IntersectionStateList *Gitsn_IntersectionStateList_new(Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_IntersectionStateList *ret = (Gitsn_IntersectionStateList *)Dz1Calloc(sizeof(Gitsn_IntersectionStateList), 1, errp);
	if (ret == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_IntersectionStateList_delAndSetNull, (void *)&ret);

		if ((ret->storage = Dz1Fifo_newDynamic(
				(Dz1DelFunc)Gitsn_IntersectionState_del,
				NULL, errp)) == NULL) ERR_OUT(errp);
		else
		{
			ret->count = Gitsn_IntersectionStateList_count;
			ret->travel = Gitsn_IntersectionStateList_travelForward;
			ret->travelForward = Gitsn_IntersectionStateList_travelForward;
			ret->travelBackward = Gitsn_IntersectionStateList_travelBackward;
			ret->get_array = Gitsn_IntersectionStateList_get_array;
			ret->add = Gitsn_IntersectionStateList_add;
			ret->extract = Gitsn_IntersectionStateList_extract;
			ret->getHead = Gitsn_IntersectionStateList_getHead;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_IntersectionStateList_delAndSetNull, (void *)&ret);
	}
	return ret;
}

static Dz1Error _Gitsn_IntersectionStateList_clone(void *ptr, Gitsn_IntersectionState *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_IntersectionStateList *p = (Gitsn_IntersectionStateList *)ptr;
	Gitsn_IntersectionState *cloned = Gitsn_IntersectionState_clone(data, &err); // normal
	err = Dz1Fifo_push(p->storage, cloned); // chk
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

Gitsn_IntersectionStateList *Gitsn_IntersectionStateList_clone(Gitsn_IntersectionStateList *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_IntersectionStateList *ret = NULL;
	if (src == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = Gitsn_IntersectionStateList_new(errp)) == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_IntersectionStateList_delAndSetNull, (void *)&ret);

		*errp = Dz1Fifo_travelForward(src->storage, (Dz1FifoTravelFunc)_Gitsn_IntersectionStateList_clone, (void *)ret);

		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_IntersectionStateList_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_IntersectionStateList_purge(Gitsn_IntersectionStateList *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_empty(p->storage);
}

void Gitsn_IntersectionStateList_del(Gitsn_IntersectionStateList *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_del(p->storage);
	Dz1Free(p);
}

