////////////////////////////////////////////////////////////////////////////////
// Gitsn_VehicleID
Gitsn_VehicleID *Gitsn_VehicleID_new(Gitsn_VehicleIDPresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_VehicleID *ret = (Gitsn_VehicleID *)Dz1Calloc(sizeof(Gitsn_VehicleID), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_VehicleID_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_VehicleIDPresent_entityID:
			// _U_prim_clone
			if (ptr && (ret->x.entityID = Gitsn_TemporaryID_clone((Gitsn_TemporaryID)ptr, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_VehicleIDPresent_stationID:
			// _U_prim_clone
			if (ptr != NULL) ret->x.stationID = *(Gitsn_StationID *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_VehicleIDPresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_VehicleID_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_VehicleID_copy(Gitsn_VehicleID *ret, Gitsn_VehicleID *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_VehicleIDPresent_entityID:
			// _U_prim_clone
			if (src->x.entityID && (ret->x.entityID = Gitsn_TemporaryID_clone(src->x.entityID, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_VehicleIDPresent_stationID:
			// _U_prim_clone
			ret->x.stationID = src->x.stationID;
			ERR_CLEAR(errp);
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_VehicleID *Gitsn_VehicleID_clone(Gitsn_VehicleID *src, Dz1Error *err)
{
	Gitsn_VehicleID *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (Gitsn_VehicleID *)Dz1Calloc(sizeof(Gitsn_VehicleID), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_VehicleID_delAndSetNull, (void *)&ret);
		if (Gitsn_VehicleID_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_VehicleID_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_VehicleID_purge(Gitsn_VehicleID *p)
{
	if (!p) return;
	switch(p->present)
	{
	case Gitsn_VehicleIDPresent_entityID:
		Gitsn_TemporaryID_del(p->x.entityID);
		break;
	case Gitsn_VehicleIDPresent_stationID:
		break;
	default:
		break;
	}
}

void Gitsn_VehicleID_del(Gitsn_VehicleID *p)
{
	if (!p) return;
	Gitsn_VehicleID_purge(p);
	Dz1Free(p);
}

void Gitsn_VehicleID_dump(Gitsn_VehicleID *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else switch(p->present)
	{
	case Gitsn_VehicleIDPresent_entityID:
		Dz1Thread_printf(Dz1T("entityID = ")); Gitsn_TemporaryID_dump(p->x.entityID, tab); 
		break;
	case Gitsn_VehicleIDPresent_stationID:
		Dz1Thread_printf(Dz1T("stationID = ")); Gitsn_StationID_dump(&p->x.stationID, tab); 
		break;
	default:
		Dz1Thread_tprintf(tab, Dz1T("??? = %d\n"), p->present);
		break;
	}
}

