bool_t Gitsn_VehicleIdent_copy(Gitsn_VehicleIdent *dst, Gitsn_VehicleIdent *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->name && (dst->name = Gitsn_DescriptiveName_clone(src->name, errp)) == NULL) ERR_OUT(errp);
	else if (src->vin && (dst->vin = Gitsn_VINstring_clone(src->vin, errp)) == NULL) ERR_OUT(errp);
	else if (src->ownerCode && (dst->ownerCode = Gitsn_IA5String_clone(src->ownerCode, errp)) == NULL) ERR_OUT(errp);
	else if (src->id && (dst->id = Gitsn_VehicleID_clone(src->id, errp)) == NULL) ERR_OUT(errp);
	else if (src->vehicleClass && (dst->vehicleClass = Gitsn_VehicleIdent_vehicleClass_clone(src->vehicleClass, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->vehicleType = src->vehicleType;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

