bool_t Gitsn_FullPositionVector_copy(Gitsn_FullPositionVector *dst, Gitsn_FullPositionVector *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->utcTime && (dst->utcTime = Gitsn_DDateTime_clone(src->utcTime, errp)) == NULL) ERR_OUT(errp);
	else if (src->speed && (dst->speed = Gitsn_TransmissionAndSpeed_clone(src->speed, errp)) == NULL) ERR_OUT(errp);
	else if (src->posAccuracy && (dst->posAccuracy = Gitsn_PositionalAccuracy_clone(src->posAccuracy, errp)) == NULL) ERR_OUT(errp);
	else if (src->posConfidence && (dst->posConfidence = Gitsn_PositionConfidenceSet_clone(src->posConfidence, errp)) == NULL) ERR_OUT(errp);
	else if (src->speedConfidence && (dst->speedConfidence = Gitsn_SpeedandHeadingandThrottleConfidence_clone(src->speedConfidence, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->lon = src->lon;
		dst->lat = src->lat;
		dst->elevation = src->elevation;
		dst->heading = src->heading;
		dst->timeConfidence = src->timeConfidence;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

