Gitsn_J1939DataItems *Gitsn_J1939DataItems_new(Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_J1939DataItems *__internal_ret = (Gitsn_J1939DataItems *)Dz1Calloc(sizeof(Gitsn_J1939DataItems), 1, errp);
	if (__internal_ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_J1939DataItems_delAndSetNull, (void *)&__internal_ret);
		
		if ((__internal_ret->tires = Gitsn_TireDataList_gen(errp)) == NULL) ERR_OUT(errp);
		else if ((__internal_ret->axles = Gitsn_AxleWeightList_gen(errp)) == NULL) ERR_OUT(errp);
		else
		{
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_J1939DataItems_delAndSetNull, (void *)&__internal_ret)
	}
	return __internal_ret;
}

bool_t Gitsn_J1939DataItems_copy(Gitsn_J1939DataItems *dst, Gitsn_J1939DataItems *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->tires && (dst->tires = Gitsn_TireDataList_clone(src->tires, errp)) == NULL) ERR_OUT(errp);
	else if (src->axles && (dst->axles = Gitsn_AxleWeightList_clone(src->axles, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->trailerWeight = src->trailerWeight;
		dst->cargoWeight = src->cargoWeight;
		dst->steeringAxleTemperature = src->steeringAxleTemperature;
		dst->driveAxleLocation = src->driveAxleLocation;
		dst->driveAxleLiftAirPressure = src->driveAxleLiftAirPressure;
		dst->driveAxleTemperature = src->driveAxleTemperature;
		dst->driveAxleLubePressure = src->driveAxleLubePressure;
		dst->steeringAxleLubePressure = src->steeringAxleLubePressure;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

