static Dz1Error Gitsn_RoadSideAlert_description_add(Gitsn_RoadSideAlert_description *p, Gitsn_ITIScodes data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_ITIScodes *temp = NULL;
	if ((temp = (Gitsn_ITIScodes *)Dz1Calloc(sizeof(Gitsn_ITIScodes), 1, &err)) == NULL) ERR_OUT(&err);
	else
	{
		pthread_cleanup_push((void (*)(void *))Gitsn_ITIScodes_del, (void *)temp);

		memcpy(temp, &data, sizeof(Gitsn_ITIScodes));
		err = Dz1Fifo_push(p->storage, temp);
		if (ERR_PROBE(&err)) ERR_OUT(&err);

		pthread_cleanup_pop(ERR_PROBE(&err)); // ((void (*)(void *))Gitsn_ITIScodes_del, (void *)temp);

	}
	return err;
}

