Gitsn_RoadSignID *Gitsn_RoadSignID_new(Gitsn_Position3D *position, 
									   Gitsn_HeadingSlice *viewAngle, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_RoadSignID *__internal_ret = (Gitsn_RoadSignID *)Dz1Calloc(sizeof(Gitsn_RoadSignID), 1, errp);
	if (__internal_ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_RoadSignID_delAndSetNull, (void *)&__internal_ret);
		
		__internal_ret->position = position;
		__internal_ret->viewAngle = viewAngle;
		ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_RoadSignID_delAndSetNull, (void *)&__internal_ret)
	}
	return __internal_ret;
}

bool_t Gitsn_RoadSignID_copy(Gitsn_RoadSignID *dst, Gitsn_RoadSignID *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->position && (dst->position = Gitsn_Position3D_clone(src->position, errp)) == NULL) ERR_OUT(errp);
	else if (src->viewAngle && (dst->viewAngle = Gitsn_HeadingSlice_clone(src->viewAngle, errp)) == NULL) ERR_OUT(errp);
	else if (src->crc && (dst->crc = Gitsn_MsgCRC_clone(src->crc, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->mutcdCode = src->mutcdCode;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_RoadSignID *Gitsn_RoadSignID_clone(Gitsn_RoadSignID *src, Dz1Error *err)
{
	Gitsn_RoadSignID *dst = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if ((dst = (Gitsn_RoadSignID *)Dz1Calloc(sizeof(Gitsn_RoadSignID), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_RoadSignID_delAndSetNull, (void *)&dst);
		if (Gitsn_RoadSignID_copy(dst, src, errp) == FALSE) ERR_SET_OUT(errp, EINVAL);
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_RoadSignID_delAndSetNull, (void *)&dst);
	}
	return dst;
}

void Gitsn_RoadSignID_purge(Gitsn_RoadSignID *p)
{
	if (p == NULL) return;
	Gitsn_Position3D_del(p->position);
	Gitsn_HeadingSlice_del(p->viewAngle);
	Gitsn_MsgCRC_del(p->crc);
}

void Gitsn_RoadSignID_del(Gitsn_RoadSignID *p)
{
	if (p == NULL) return;
	Gitsn_RoadSignID_purge(p);
	Dz1Free(p);
}

void Gitsn_RoadSignID_dump(Gitsn_RoadSignID *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else
	{
		Dz1Thread_printf(Dz1T("{\n")); tab++;
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("position = ")); Gitsn_Position3D_dump(p->position, tab); 
		Dz1Thread_tprintf(tab, Dz1T("viewAngle = ")); Gitsn_HeadingSlice_dump(p->viewAngle, tab); 
		Dz1Thread_tprintf(tab, Dz1T("mutcdCode = %s(%d)\n"), Gitsn_MUTCDCodeStr(p->mutcdCode), p->mutcdCode);
		Dz1Thread_tprintf(tab, Dz1T("crc = ")); Gitsn_MsgCRC_dump(p->crc, tab); 
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
	}
}
