// Gitsn_TravelerDataFrame_msgId
Gitsn_TravelerDataFrame_msgId *Gitsn_TravelerDataFrame_msgId_new(Gitsn_TravelerDataFrame_msgIdPresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_TravelerDataFrame_msgId *ret = (Gitsn_TravelerDataFrame_msgId *)Dz1Calloc(sizeof(Gitsn_TravelerDataFrame_msgId), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_TravelerDataFrame_msgId_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_TravelerDataFrame_msgIdPresent_furtherInfoID:
			// _U_prim_clone
			if (ptr != NULL) ret->x.furtherInfoID = *(Gitsn_FurtherInfoID *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TravelerDataFrame_msgIdPresent_roadSignID:
			// _U_cst_clone
			if (ptr != NULL) ret->x.roadSignID = (Gitsn_RoadSignID *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TravelerDataFrame_msgIdPresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_TravelerDataFrame_msgId_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_TravelerDataFrame_msgId_copy(Gitsn_TravelerDataFrame_msgId *ret, Gitsn_TravelerDataFrame_msgId *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_TravelerDataFrame_msgIdPresent_furtherInfoID:
			// _U_prim_clone
			ret->x.furtherInfoID = src->x.furtherInfoID;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TravelerDataFrame_msgIdPresent_roadSignID:
			// _U_cst_clone
			if (src->x.roadSignID && (ret->x.roadSignID = Gitsn_RoadSignID_clone(src->x.roadSignID, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

