bool_t Gitsn_NodeAttributeSetLL_copy(Gitsn_NodeAttributeSetLL *dst, Gitsn_NodeAttributeSetLL *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->localNode && (dst->localNode = Gitsn_NodeAttributeLLList_clone(src->localNode, errp)) == NULL) ERR_OUT(errp);
	else if (src->disabled && (dst->disabled = Gitsn_SegmentAttributeLLList_clone(src->disabled, errp)) == NULL) ERR_OUT(errp);
	else if (src->enabled && (dst->enabled = Gitsn_SegmentAttributeLLList_clone(src->enabled, errp)) == NULL) ERR_OUT(errp);
	else if (src->data && (dst->data = Gitsn_LaneDataAttributeList_clone(src->data, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->dWidth = src->dWidth;
		dst->dElevation = src->dElevation;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

