// Gitsn_OffsetSystem_offset
Gitsn_OffsetSystem_offset *Gitsn_OffsetSystem_offset_new(Gitsn_OffsetSystem_offsetPresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_OffsetSystem_offset *ret = (Gitsn_OffsetSystem_offset *)Dz1Calloc(sizeof(Gitsn_OffsetSystem_offset), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_OffsetSystem_offset_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_OffsetSystem_offsetPresent_xy:
			// _U_cst_clone
			if (ptr != NULL) ret->x.xy = (Gitsn_NodeListXY *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_OffsetSystem_offsetPresent_ll:
			// _U_cst_clone
			if (ptr != NULL) ret->x.ll = (Gitsn_NodeListLL *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_OffsetSystem_offsetPresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_OffsetSystem_offset_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_OffsetSystem_offset_copy(Gitsn_OffsetSystem_offset *ret, Gitsn_OffsetSystem_offset *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_OffsetSystem_offsetPresent_xy:
			// _U_cst_clone
			if (src->x.xy && (ret->x.xy = Gitsn_NodeListXY_clone(src->x.xy, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_OffsetSystem_offsetPresent_ll:
			// _U_cst_clone
			if (src->x.ll && (ret->x.ll = Gitsn_NodeListLL_clone(src->x.ll, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_OffsetSystem_offset *Gitsn_OffsetSystem_offset_clone(Gitsn_OffsetSystem_offset *src, Dz1Error *err)
{
	Gitsn_OffsetSystem_offset *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (Gitsn_OffsetSystem_offset *)Dz1Calloc(sizeof(Gitsn_OffsetSystem_offset), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_OffsetSystem_offset_delAndSetNull, (void *)&ret);
		if (Gitsn_OffsetSystem_offset_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_OffsetSystem_offset_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_OffsetSystem_offset_purge(Gitsn_OffsetSystem_offset *p)
{
	if (!p) return;
	switch(p->present)
	{
	case Gitsn_OffsetSystem_offsetPresent_xy:
		Gitsn_NodeListXY_del(p->x.xy);
		break;
	case Gitsn_OffsetSystem_offsetPresent_ll:
		Gitsn_NodeListLL_del(p->x.ll);
		break;
	default:
		break;
	}
}

void Gitsn_OffsetSystem_offset_del(Gitsn_OffsetSystem_offset *p)
{
	if (!p) return;
	Gitsn_OffsetSystem_offset_purge(p);
	Dz1Free(p);
}

