////////////////////////////////////////////////////////////////////////////////
// Gitsn_RegionList
static Dz1Error Gitsn_RegionList_add(Gitsn_RegionList *p, Gitsn_RegionOffsets *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	err = Dz1Fifo_push(p->storage, data);
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

static Gitsn_RegionOffsets *Gitsn_RegionList_extract(Gitsn_RegionList *p, Gitsn_RegionOffsets *ptr)
{
	return (Gitsn_RegionOffsets *)Dz1Fifo_extract(p->storage, ptr);
}

typedef struct Gitsn_RegionListMkArrArg
{
	Gitsn_RegionOffsets **arr;
	unsigned int idx;
} Gitsn_RegionListMkArrArg;

static Dz1Error _Gitsn_RegionList_get_array(void *ptr, Gitsn_RegionOffsets *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_RegionListMkArrArg *arg = (Gitsn_RegionListMkArrArg *)ptr;
	arg->arr[arg->idx++] = p;
	return err;
}

static Gitsn_RegionOffsets **Gitsn_RegionList_get_array(Gitsn_RegionList *p, unsigned int *ret_cnt, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err == NULL ? &_err : err;
	Gitsn_RegionOffsets **ret = NULL;
	unsigned int cnt = 0;
	if (p == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = (Gitsn_RegionOffsets **)Dz1Calloc(sizeof(Gitsn_RegionOffsets *), (cnt = p->count(p)) + 1, errp)) == NULL) ERR_OUT(errp);
	else
	{
		Gitsn_RegionListMkArrArg arg = { ret, 0 };
		pthread_cleanup_push(Dz1Memory_cancel, (void *)ret);

		*errp = p->travel(p, _Gitsn_RegionList_get_array, (void *)&arg);
		if (ERR_PROBE(errp)) ERR_OUT(errp);
		else
		{
			if (ret_cnt) (*ret_cnt) = cnt;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Dz1Memory_cancel, (void *)ret);
	}
	if (ERR_PROBE(errp)) ret = NULL;
	return ret;
}

static Dz1Error Gitsn_RegionList_travelForward(Gitsn_RegionList *p, Dz1Error (*func)(void *ptr, Gitsn_RegionOffsets *data), void *ptr)
{
	return Dz1Fifo_travelForward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Dz1Error Gitsn_RegionList_travelBackward(Gitsn_RegionList *p, Dz1Error (*func)(void *ptr, Gitsn_RegionOffsets *data), void *ptr)
{
	return Dz1Fifo_travelBackward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Gitsn_RegionOffsets *Gitsn_RegionList_getHead(Gitsn_RegionList *p)
{
	return (Gitsn_RegionOffsets *)Dz1Fifo_getFirst(p->storage);
}

static unsigned int Gitsn_RegionList_count(Gitsn_RegionList *p)
{
	unsigned int ret = Dz1Fifo_count(p->storage);
	return ret;
}

Gitsn_RegionList *Gitsn_RegionList_new(Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_RegionList *ret = (Gitsn_RegionList *)Dz1Calloc(sizeof(Gitsn_RegionList), 1, errp);
	if (ret == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_RegionList_delAndSetNull, (void *)&ret);

		if ((ret->storage = Dz1Fifo_newDynamic(
				(Dz1DelFunc)Gitsn_RegionOffsets_del,
				NULL, errp)) == NULL) ERR_OUT(errp);
		else
		{
			ret->count = Gitsn_RegionList_count;
			ret->travel = Gitsn_RegionList_travelForward;
			ret->travelForward = Gitsn_RegionList_travelForward;
			ret->travelBackward = Gitsn_RegionList_travelBackward;
			ret->get_array = Gitsn_RegionList_get_array;
			ret->add = Gitsn_RegionList_add;
			ret->extract = Gitsn_RegionList_extract;
			ret->getHead = Gitsn_RegionList_getHead;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_RegionList_delAndSetNull, (void *)&ret);
	}
	return ret;
}

static Dz1Error _Gitsn_RegionList_clone(void *ptr, Gitsn_RegionOffsets *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_RegionList *p = (Gitsn_RegionList *)ptr;
	Gitsn_RegionOffsets *cloned = Gitsn_RegionOffsets_clone(data, &err); // normal
	err = Dz1Fifo_push(p->storage, cloned); // chk
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

Gitsn_RegionList *Gitsn_RegionList_clone(Gitsn_RegionList *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_RegionList *ret = NULL;
	if (src == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = Gitsn_RegionList_new(errp)) == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_RegionList_delAndSetNull, (void *)&ret);

		*errp = Dz1Fifo_travelForward(src->storage, (Dz1FifoTravelFunc)_Gitsn_RegionList_clone, (void *)ret);

		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_RegionList_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_RegionList_purge(Gitsn_RegionList *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_empty(p->storage);
}

void Gitsn_RegionList_del(Gitsn_RegionList *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_del(p->storage);
	Dz1Free(p);
}

static Dz1Error _Gitsn_RegionList_dump(void *ptr, Gitsn_RegionOffsets *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Dz1ListFDumpArg2 *arg = (Dz1ListFDumpArg2 *)ptr;
	int tab = *(int *)arg->tab;
	Dz1Thread_tprintf(tab, Dz1T("entry = ")); Gitsn_RegionOffsets_dump(p, tab);
	return err;
}

void Gitsn_RegionList_dump(Gitsn_RegionList *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else
	{
		Dz1ListFDumpArg2 arg = { NULL, &tab };
		Dz1Thread_tprintf(tab, Dz1T("{\n")); tab++;
		p->travel(p, _Gitsn_RegionList_dump, (void *)&arg);
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
	}
}
