////////////////////////////////////////////////////////////////////////////////
// Gitsn_ValidRegion_area
Gitsn_ValidRegion_area *Gitsn_ValidRegion_area_new(Gitsn_ValidRegion_areaPresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_ValidRegion_area *ret = (Gitsn_ValidRegion_area *)Dz1Calloc(sizeof(Gitsn_ValidRegion_area), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_ValidRegion_area_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_ValidRegion_areaPresent_shapePointSet:
			// _U_cst_clone
			if (ptr != NULL) ret->x.shapePointSet = (Gitsn_ShapePointSet *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_ValidRegion_areaPresent_circle:
			// _U_cst_clone
			if (ptr != NULL) ret->x.circle = (Gitsn_Circle *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_ValidRegion_areaPresent_regionPointSet:
			// _U_cst_clone
			if (ptr != NULL) ret->x.regionPointSet = (Gitsn_RegionPointSet *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_ValidRegion_areaPresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_ValidRegion_area_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_ValidRegion_area_copy(Gitsn_ValidRegion_area *ret, Gitsn_ValidRegion_area *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_ValidRegion_areaPresent_shapePointSet:
			// _U_cst_clone
			if (src->x.shapePointSet && (ret->x.shapePointSet = Gitsn_ShapePointSet_clone(src->x.shapePointSet, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_ValidRegion_areaPresent_circle:
			// _U_cst_clone
			if (src->x.circle && (ret->x.circle = Gitsn_Circle_clone(src->x.circle, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_ValidRegion_areaPresent_regionPointSet:
			// _U_cst_clone
			if (src->x.regionPointSet && (ret->x.regionPointSet = Gitsn_RegionPointSet_clone(src->x.regionPointSet, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_ValidRegion_area *Gitsn_ValidRegion_area_clone(Gitsn_ValidRegion_area *src, Dz1Error *err)
{
	Gitsn_ValidRegion_area *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (Gitsn_ValidRegion_area *)Dz1Calloc(sizeof(Gitsn_ValidRegion_area), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_ValidRegion_area_delAndSetNull, (void *)&ret);
		if (Gitsn_ValidRegion_area_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_ValidRegion_area_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_ValidRegion_area_purge(Gitsn_ValidRegion_area *p)
{
	if (!p) return;
	switch(p->present)
	{
	case Gitsn_ValidRegion_areaPresent_shapePointSet:
		Gitsn_ShapePointSet_del(p->x.shapePointSet);
		break;
	case Gitsn_ValidRegion_areaPresent_circle:
		Gitsn_Circle_del(p->x.circle);
		break;
	case Gitsn_ValidRegion_areaPresent_regionPointSet:
		Gitsn_RegionPointSet_del(p->x.regionPointSet);
		break;
	default:
		break;
	}
}

void Gitsn_ValidRegion_area_del(Gitsn_ValidRegion_area *p)
{
	if (!p) return;
	Gitsn_ValidRegion_area_purge(p);
	Dz1Free(p);
}

void Gitsn_ValidRegion_area_dump(Gitsn_ValidRegion_area *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else switch(p->present)
	{
	case Gitsn_ValidRegion_areaPresent_shapePointSet:
		Dz1Thread_printf(Dz1T("shapePointSet = ")); Gitsn_ShapePointSet_dump(p->x.shapePointSet, tab); 
		break;
	case Gitsn_ValidRegion_areaPresent_circle:
		Dz1Thread_printf(Dz1T("circle = ")); Gitsn_Circle_dump(p->x.circle, tab); 
		break;
	case Gitsn_ValidRegion_areaPresent_regionPointSet:
		Dz1Thread_printf(Dz1T("regionPointSet = ")); Gitsn_RegionPointSet_dump(p->x.regionPointSet, tab); 
		break;
	default:
		Dz1Thread_tprintf(tab, Dz1T("??? = %d\n"), p->present);
		break;
	}
}

