////////////////////////////////////////////////////////////////////////////////
// Gitsn_GeographicalPath_description
Gitsn_GeographicalPath_description *Gitsn_GeographicalPath_description_new(Gitsn_GeographicalPath_descriptionPresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_GeographicalPath_description *ret = (Gitsn_GeographicalPath_description *)Dz1Calloc(sizeof(Gitsn_GeographicalPath_description), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_GeographicalPath_description_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_GeographicalPath_descriptionPresent_path:
			// _U_cst_clone
			if (ptr != NULL) ret->x.path = (Gitsn_OffsetSystem *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_GeographicalPath_descriptionPresent_geometry:
			// _U_cst_clone
			if (ptr != NULL) ret->x.geometry = (Gitsn_GeometricProjection *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_GeographicalPath_descriptionPresent_oldRegion:
			// _U_cst_clone
			if (ptr != NULL) ret->x.oldRegion = (Gitsn_ValidRegion *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_GeographicalPath_descriptionPresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_GeographicalPath_description_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_GeographicalPath_description_copy(Gitsn_GeographicalPath_description *ret, Gitsn_GeographicalPath_description *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_GeographicalPath_descriptionPresent_path:
			// _U_cst_clone
			if (src->x.path && (ret->x.path = Gitsn_OffsetSystem_clone(src->x.path, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_GeographicalPath_descriptionPresent_geometry:
			// _U_cst_clone
			if (src->x.geometry && (ret->x.geometry = Gitsn_GeometricProjection_clone(src->x.geometry, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_GeographicalPath_descriptionPresent_oldRegion:
			// _U_cst_clone
			if (src->x.oldRegion && (ret->x.oldRegion = Gitsn_ValidRegion_clone(src->x.oldRegion, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_GeographicalPath_description *Gitsn_GeographicalPath_description_clone(Gitsn_GeographicalPath_description *src, Dz1Error *err)
{
	Gitsn_GeographicalPath_description *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (Gitsn_GeographicalPath_description *)Dz1Calloc(sizeof(Gitsn_GeographicalPath_description), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_GeographicalPath_description_delAndSetNull, (void *)&ret);
		if (Gitsn_GeographicalPath_description_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_GeographicalPath_description_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_GeographicalPath_description_purge(Gitsn_GeographicalPath_description *p)
{
	if (!p) return;
	switch(p->present)
	{
	case Gitsn_GeographicalPath_descriptionPresent_path:
		Gitsn_OffsetSystem_del(p->x.path);
		break;
	case Gitsn_GeographicalPath_descriptionPresent_geometry:
		Gitsn_GeometricProjection_del(p->x.geometry);
		break;
	case Gitsn_GeographicalPath_descriptionPresent_oldRegion:
		Gitsn_ValidRegion_del(p->x.oldRegion);
		break;
	default:
		break;
	}
}

void Gitsn_GeographicalPath_description_del(Gitsn_GeographicalPath_description *p)
{
	if (!p) return;
	Gitsn_GeographicalPath_description_purge(p);
	Dz1Free(p);
}

void Gitsn_GeographicalPath_description_dump(Gitsn_GeographicalPath_description *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else switch(p->present)
	{
	case Gitsn_GeographicalPath_descriptionPresent_path:
		Dz1Thread_printf(Dz1T("path = ")); Gitsn_OffsetSystem_dump(p->x.path, tab); 
		break;
	case Gitsn_GeographicalPath_descriptionPresent_geometry:
		Dz1Thread_printf(Dz1T("geometry = ")); Gitsn_GeometricProjection_dump(p->x.geometry, tab); 
		break;
	case Gitsn_GeographicalPath_descriptionPresent_oldRegion:
		Dz1Thread_printf(Dz1T("oldRegion = ")); Gitsn_ValidRegion_dump(p->x.oldRegion, tab); 
		break;
	default:
		Dz1Thread_tprintf(tab, Dz1T("??? = %d\n"), p->present);
		break;
	}
}

