{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_WorkZone *ret = (Gitsn_WorkZone *)Dz1Calloc(sizeof(Gitsn_WorkZone), 1, errp);
	if (ret == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_WorkZone_delAndSetNull, (void *)&ret);

		if ((ret->storage = Dz1Fifo_newDynamic(
				(Dz1DelFunc)Gitsn_WorkZone_element_del,
				NULL, errp)) == NULL) ERR_OUT(errp);
		else
		{
			ret->count = Gitsn_WorkZone_count;
			ret->travel = Gitsn_WorkZone_travelForward;
			ret->travelForward = Gitsn_WorkZone_travelForward;
			ret->travelBackward = Gitsn_WorkZone_travelBackward;
			ret->get_array = Gitsn_WorkZone_get_array;
			ret->add = Gitsn_WorkZone_add;
			ret->extract = Gitsn_WorkZone_extract;
			ret->getHead = Gitsn_WorkZone_getHead;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_WorkZone_delAndSetNull, (void *)&ret);
	}
	return ret;
}

static Dz1Error _Gitsn_WorkZone_clone(void *ptr, Gitsn_WorkZone_element *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_WorkZone *p = (Gitsn_WorkZone *)ptr;
	Gitsn_WorkZone_element *cloned = Gitsn_WorkZone_element_clone(data, &err); // normal
	err = Dz1Fifo_push(p->storage, cloned); // chk
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

Gitsn_WorkZone *Gitsn_WorkZone_clone(Gitsn_WorkZone *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_WorkZone *ret = NULL;
	if (src == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = Gitsn_WorkZone_new(errp)) == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_WorkZone_delAndSetNull, (void *)&ret);

		*errp = Dz1Fifo_travelForward(src->storage, (Dz1FifoTravelFunc)_Gitsn_WorkZone_clone, (void *)ret);

		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_WorkZone_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_WorkZone_purge(Gitsn_WorkZone *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_empty(p->storage);
}

void Gitsn_WorkZone_del(Gitsn_WorkZone *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_del(p->storage);
	Dz1Free(p);
}

