// Gitsn_SpeedLimit_element_item
Gitsn_SpeedLimit_element_item *Gitsn_SpeedLimit_element_item_new(Gitsn_SpeedLimit_element_itemPresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_SpeedLimit_element_item *ret = (Gitsn_SpeedLimit_element_item *)Dz1Calloc(sizeof(Gitsn_SpeedLimit_element_item), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_SpeedLimit_element_item_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_SpeedLimit_element_itemPresent_itis:
			// _U_prim_clone
			if (ptr != NULL) ret->x.itis = *(Gitsn_ITIScodes *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_SpeedLimit_element_itemPresent_text:
			// _U_prim_clone
			if (ptr && (ret->x.text = Gitsn_ITIStext_clone((Gitsn_ITIStext)ptr, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_SpeedLimit_element_itemPresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_SpeedLimit_element_item_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_SpeedLimit_element_item_copy(Gitsn_SpeedLimit_element_item *ret, Gitsn_SpeedLimit_element_item *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_SpeedLimit_element_itemPresent_itis:
			// _U_prim_clone
			ret->x.itis = src->x.itis;
			ERR_CLEAR(errp);
			break;
		case Gitsn_SpeedLimit_element_itemPresent_text:
			// _U_prim_clone
			if (src->x.text && (ret->x.text = Gitsn_ITIStext_clone(src->x.text, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_SpeedLimit_element_item *Gitsn_SpeedLimit_element_item_clone(Gitsn_SpeedLimit_element_item *src, Dz1Error *err)
{
	Gitsn_SpeedLimit_element_item *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (Gitsn_SpeedLimit_element_item *)Dz1Calloc(sizeof(Gitsn_SpeedLimit_element_item), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_SpeedLimit_element_item_delAndSetNull, (void *)&ret);
		if (Gitsn_SpeedLimit_element_item_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_SpeedLimit_element_item_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_SpeedLimit_element_item_purge(Gitsn_SpeedLimit_element_item *p)
{
	if (!p) return;
	switch(p->present)
	{
	case Gitsn_SpeedLimit_element_itemPresent_itis:
		break;
	case Gitsn_SpeedLimit_element_itemPresent_text:
		Gitsn_ITIStext_del(p->x.text);
		break;
	default:
		break;
	}
}

void Gitsn_SpeedLimit_element_item_del(Gitsn_SpeedLimit_element_item *p)
{
	if (!p) return;
	Gitsn_SpeedLimit_element_item_purge(p);
	Dz1Free(p);
}

void Gitsn_SpeedLimit_element_item_dump(Gitsn_SpeedLimit_element_item *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else switch(p->present)
	{
	case Gitsn_SpeedLimit_element_itemPresent_itis:
		Dz1Thread_printf(Dz1T("itis = ")); Gitsn_ITIScodes_dump(&p->x.itis, tab); 
		break;
	case Gitsn_SpeedLimit_element_itemPresent_text:
		Dz1Thread_printf(Dz1T("text = ")); Gitsn_ITIStext_dump(p->x.text, tab); 
		break;
	default:
		Dz1Thread_tprintf(tab, Dz1T("??? = %d\n"), p->present);
		break;
	}
}

