Gitsn_TravelerDataFrame_content *Gitsn_TravelerDataFrame_content_new(Gitsn_TravelerDataFrame_contentPresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_TravelerDataFrame_content *ret = (Gitsn_TravelerDataFrame_content *)Dz1Calloc(sizeof(Gitsn_TravelerDataFrame_content), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_TravelerDataFrame_content_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_TravelerDataFrame_contentPresent_advisory:
			// _U_cst_clone
			if (ptr != NULL) ret->x.advisory = (Gitsn_ITIScodesAndText *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TravelerDataFrame_contentPresent_workZone:
			// _U_cst_clone
			if (ptr != NULL) ret->x.workZone = (Gitsn_WorkZone *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TravelerDataFrame_contentPresent_genericSign:
			// _U_cst_clone
			if (ptr != NULL) ret->x.genericSign = (Gitsn_GenericSignage *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TravelerDataFrame_contentPresent_speedLimit:
			// _U_cst_clone
			if (ptr != NULL) ret->x.speedLimit = (Gitsn_SpeedLimit *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TravelerDataFrame_contentPresent_exitService:
			// _U_cst_clone
			if (ptr != NULL) ret->x.exitService = (Gitsn_ExitService *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TravelerDataFrame_contentPresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_TravelerDataFrame_content_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_TravelerDataFrame_content_copy(Gitsn_TravelerDataFrame_content *ret, Gitsn_TravelerDataFrame_content *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_TravelerDataFrame_contentPresent_advisory:
			// _U_cst_clone
			if (src->x.advisory && (ret->x.advisory = Gitsn_ITIScodesAndText_clone(src->x.advisory, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_TravelerDataFrame_contentPresent_workZone:
			// _U_cst_clone
			if (src->x.workZone && (ret->x.workZone = Gitsn_WorkZone_clone(src->x.workZone, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_TravelerDataFrame_contentPresent_genericSign:
			// _U_cst_clone
			if (src->x.genericSign && (ret->x.genericSign = Gitsn_GenericSignage_clone(src->x.genericSign, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_TravelerDataFrame_contentPresent_speedLimit:
			// _U_cst_clone
			if (src->x.speedLimit && (ret->x.speedLimit = Gitsn_SpeedLimit_clone(src->x.speedLimit, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		case Gitsn_TravelerDataFrame_contentPresent_exitService:
			// _U_cst_clone
			if (src->x.exitService && (ret->x.exitService = Gitsn_ExitService_clone(src->x.exitService, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_TravelerDataFrame_content *Gitsn_TravelerDataFrame_content_clone(Gitsn_TravelerDataFrame_content *src, Dz1Error *err)
{
	Gitsn_TravelerDataFrame_content *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (Gitsn_TravelerDataFrame_content *)Dz1Calloc(sizeof(Gitsn_TravelerDataFrame_content), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_TravelerDataFrame_content_delAndSetNull, (void *)&ret);
		if (Gitsn_TravelerDataFrame_content_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_TravelerDataFrame_content_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_TravelerDataFrame_content_purge(Gitsn_TravelerDataFrame_content *p)
{
	if (!p) return;
	switch(p->present)
	{
	case Gitsn_TravelerDataFrame_contentPresent_advisory:
		Gitsn_ITIScodesAndText_del(p->x.advisory);
		break;
	case Gitsn_TravelerDataFrame_contentPresent_workZone:
		Gitsn_WorkZone_del(p->x.workZone);
		break;
	case Gitsn_TravelerDataFrame_contentPresent_genericSign:
		Gitsn_GenericSignage_del(p->x.genericSign);
		break;
	case Gitsn_TravelerDataFrame_contentPresent_speedLimit:
		Gitsn_SpeedLimit_del(p->x.speedLimit);
		break;
	case Gitsn_TravelerDataFrame_contentPresent_exitService:
		Gitsn_ExitService_del(p->x.exitService);
		break;
	default:
		break;
	}
}

void Gitsn_TravelerDataFrame_content_del(Gitsn_TravelerDataFrame_content *p)
{
	if (!p) return;
	Gitsn_TravelerDataFrame_content_purge(p);
	Dz1Free(p);
}

void Gitsn_TravelerDataFrame_content_dump(Gitsn_TravelerDataFrame_content *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else switch(p->present)
	{
	case Gitsn_TravelerDataFrame_contentPresent_advisory:
		Dz1Thread_printf(Dz1T("advisory = ")); Gitsn_ITIScodesAndText_dump(p->x.advisory, tab); 
		break;
	case Gitsn_TravelerDataFrame_contentPresent_workZone:
		Dz1Thread_printf(Dz1T("workZone = ")); Gitsn_WorkZone_dump(p->x.workZone, tab); 
		break;
	case Gitsn_TravelerDataFrame_contentPresent_genericSign:
		Dz1Thread_printf(Dz1T("genericSign = ")); Gitsn_GenericSignage_dump(p->x.genericSign, tab); 
		break;
	case Gitsn_TravelerDataFrame_contentPresent_speedLimit:
		Dz1Thread_printf(Dz1T("speedLimit = ")); Gitsn_SpeedLimit_dump(p->x.speedLimit, tab); 
		break;
	case Gitsn_TravelerDataFrame_contentPresent_exitService:
		Dz1Thread_printf(Dz1T("exitService = ")); Gitsn_ExitService_dump(p->x.exitService, tab); 
		break;
	default:
		Dz1Thread_tprintf(tab, Dz1T("??? = %d\n"), p->present);
		break;
	}
}

