static Dz1Error Gitsn_TravelerDataFrameList_add(Gitsn_TravelerDataFrameList *p, Gitsn_TravelerDataFrame *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	err = Dz1Fifo_push(p->storage, data);
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

static Gitsn_TravelerDataFrame *Gitsn_TravelerDataFrameList_extract(Gitsn_TravelerDataFrameList *p, Gitsn_TravelerDataFrame *ptr)
{
	return (Gitsn_TravelerDataFrame *)Dz1Fifo_extract(p->storage, ptr);
}

typedef struct Gitsn_TravelerDataFrameListMkArrArg
{
	Gitsn_TravelerDataFrame **arr;
	unsigned int idx;
} Gitsn_TravelerDataFrameListMkArrArg;

static Dz1Error _Gitsn_TravelerDataFrameList_get_array(void *ptr, Gitsn_TravelerDataFrame *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_TravelerDataFrameListMkArrArg *arg = (Gitsn_TravelerDataFrameListMkArrArg *)ptr;
	arg->arr[arg->idx++] = p;
	return err;
}

static Gitsn_TravelerDataFrame **Gitsn_TravelerDataFrameList_get_array(Gitsn_TravelerDataFrameList *p, unsigned int *ret_cnt, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err == NULL ? &_err : err;
	Gitsn_TravelerDataFrame **ret = NULL;
	unsigned int cnt = 0;
	if (p == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = (Gitsn_TravelerDataFrame **)Dz1Calloc(sizeof(Gitsn_TravelerDataFrame *), (cnt = p->count(p)) + 1, errp)) == NULL) ERR_OUT(errp);
	else
	{
		Gitsn_TravelerDataFrameListMkArrArg arg = { ret, 0 };
		pthread_cleanup_push(Dz1Memory_cancel, (void *)ret);

		*errp = p->travel(p, _Gitsn_TravelerDataFrameList_get_array, (void *)&arg);
		if (ERR_PROBE(errp)) ERR_OUT(errp);
		else
		{
			if (ret_cnt) (*ret_cnt) = cnt;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Dz1Memory_cancel, (void *)ret);
	}
	if (ERR_PROBE(errp)) ret = NULL;
	return ret;
}

static Dz1Error Gitsn_TravelerDataFrameList_travelForward(Gitsn_TravelerDataFrameList *p, Dz1Error (*func)(void *ptr, Gitsn_TravelerDataFrame *data), void *ptr)
{
	return Dz1Fifo_travelForward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Dz1Error Gitsn_TravelerDataFrameList_travelBackward(Gitsn_TravelerDataFrameList *p, Dz1Error (*func)(void *ptr, Gitsn_TravelerDataFrame *data), void *ptr)
{
	return Dz1Fifo_travelBackward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

