////////////////////////////////////////////////////////////////////////////////
// Gitsn_TrafficLightID
Gitsn_TrafficLightID *Gitsn_TrafficLightID_new(Gitsn_TrafficLightIDPresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_TrafficLightID *ret = (Gitsn_TrafficLightID *)Dz1Calloc(sizeof(Gitsn_TrafficLightID), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_TrafficLightID_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_TrafficLightIDPresent_id:
			// _U_prim_clone
			if (ptr != NULL) ret->x.id = *(Gitsn_INTEGER *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TrafficLightIDPresent_oid:
			// _U_cst_clone
			if (ptr != NULL) ret->x.oid = (Gitsn_OBJECTIDENTIFIER *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TrafficLightIDPresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_TrafficLightID_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_TrafficLightID_copy(Gitsn_TrafficLightID *ret, Gitsn_TrafficLightID *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_TrafficLightIDPresent_id:
			// _U_prim_clone
			ret->x.id = src->x.id;
			ERR_CLEAR(errp);
			break;
		case Gitsn_TrafficLightIDPresent_oid:
			// _U_cst_clone
			if (src->x.oid && (ret->x.oid = Gitsn_OBJECTIDENTIFIER_clone(src->x.oid, errp)) == NULL) ERR_OUT(errp);
			else {ERR_CLEAR(errp); }
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_TrafficLightID *Gitsn_TrafficLightID_clone(Gitsn_TrafficLightID *src, Dz1Error *err)
{
	Gitsn_TrafficLightID *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (Gitsn_TrafficLightID *)Dz1Calloc(sizeof(Gitsn_TrafficLightID), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_TrafficLightID_delAndSetNull, (void *)&ret);
		if (Gitsn_TrafficLightID_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_TrafficLightID_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_TrafficLightID_purge(Gitsn_TrafficLightID *p)
{
	if (!p) return;
	switch(p->present)
	{
	case Gitsn_TrafficLightIDPresent_id:
		break;
	case Gitsn_TrafficLightIDPresent_oid:
		Gitsn_OBJECTIDENTIFIER_del(p->x.oid);
		break;
	default:
		break;
	}
}

void Gitsn_TrafficLightID_del(Gitsn_TrafficLightID *p)
{
	if (!p) return;
	Gitsn_TrafficLightID_purge(p);
	Dz1Free(p);
}

void Gitsn_TrafficLightID_dump(Gitsn_TrafficLightID *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else switch(p->present)
	{
	case Gitsn_TrafficLightIDPresent_id:
		Dz1Thread_printf(Dz1T("id = ")); Gitsn_INTEGER_dump(&p->x.id, tab); 
		break;
	case Gitsn_TrafficLightIDPresent_oid:
		Dz1Thread_printf(Dz1T("oid = ")); Gitsn_OBJECTIDENTIFIER_dump(p->x.oid, tab); 
		break;
	default:
		Dz1Thread_tprintf(tab, Dz1T("??? = %d\n"), p->present);
		break;
	}
}

