static Dz1Error Gitsn_TrafficLightStatusList_add(Gitsn_TrafficLightStatusList *p, Gitsn_TrafficLightStatus *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	err = Dz1Fifo_push(p->storage, data);
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

static Gitsn_TrafficLightStatus *Gitsn_TrafficLightStatusList_extract(Gitsn_TrafficLightStatusList *p, Gitsn_TrafficLightStatus *ptr)
{
	return (Gitsn_TrafficLightStatus *)Dz1Fifo_extract(p->storage, ptr);
}

typedef struct Gitsn_TrafficLightStatusListMkArrArg
{
	Gitsn_TrafficLightStatus **arr;
	unsigned int idx;
} Gitsn_TrafficLightStatusListMkArrArg;

static Dz1Error _Gitsn_TrafficLightStatusList_get_array(void *ptr, Gitsn_TrafficLightStatus *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_TrafficLightStatusListMkArrArg *arg = (Gitsn_TrafficLightStatusListMkArrArg *)ptr;
	arg->arr[arg->idx++] = p;
	return err;
}

static Gitsn_TrafficLightStatus **Gitsn_TrafficLightStatusList_get_array(Gitsn_TrafficLightStatusList *p, unsigned int *ret_cnt, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err == NULL ? &_err : err;
	Gitsn_TrafficLightStatus **ret = NULL;
	unsigned int cnt = 0;
	if (p == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = (Gitsn_TrafficLightStatus **)Dz1Calloc(sizeof(Gitsn_TrafficLightStatus *), (cnt = p->count(p)) + 1, errp)) == NULL) ERR_OUT(errp);
	else
	{
		Gitsn_TrafficLightStatusListMkArrArg arg = { ret, 0 };
		pthread_cleanup_push(Dz1Memory_cancel, (void *)ret);

		*errp = p->travel(p, _Gitsn_TrafficLightStatusList_get_array, (void *)&arg);
		if (ERR_PROBE(errp)) ERR_OUT(errp);
		else
		{
			if (ret_cnt) (*ret_cnt) = cnt;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Dz1Memory_cancel, (void *)ret);
	}
	if (ERR_PROBE(errp)) ret = NULL;
	return ret;
}

static Dz1Error Gitsn_TrafficLightStatusList_travelForward(Gitsn_TrafficLightStatusList *p, Dz1Error (*func)(void *ptr, Gitsn_TrafficLightStatus *data), void *ptr)
{
	return Dz1Fifo_travelForward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Dz1Error Gitsn_TrafficLightStatusList_travelBackward(Gitsn_TrafficLightStatusList *p, Dz1Error (*func)(void *ptr, Gitsn_TrafficLightStatus *data), void *ptr)
{
	return Dz1Fifo_travelBackward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

