bool_t Gitsn_DetectedObjectCommonData_copy(Gitsn_DetectedObjectCommonData *dst, Gitsn_DetectedObjectCommonData *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->pos && (dst->pos = Gitsn_PositionOffsetXYZ_clone(src->pos, errp)) == NULL) ERR_OUT(errp);
	else if (src->posConfidence && (dst->posConfidence = Gitsn_PositionConfidenceSet_clone(src->posConfidence, errp)) == NULL) ERR_OUT(errp);
	else if (src->accel4way && (dst->accel4way = Gitsn_AccelerationSet4Way_clone(src->accel4way, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->objType = src->objType;
		dst->objTypeCfd = src->objTypeCfd;
		dst->objectID = src->objectID;
		dst->measurementTime = src->measurementTime;
		dst->timeConfidence = src->timeConfidence;
		dst->speed = src->speed;
		dst->speedConfidence = src->speedConfidence;
		dst->speedZ = src->speedZ;
		dst->speedConfidenceZ = src->speedConfidenceZ;
		dst->heading = src->heading;
		dst->headingConf = src->headingConf;
		dst->accCfdX = src->accCfdX;
		dst->accCfdY = src->accCfdY;
		dst->accCfdZ = src->accCfdZ;
		dst->accCfdYaw = src->accCfdYaw;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

