Gitsn_DetectedVehicleData *Gitsn_DetectedVehicleData_new(Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_DetectedVehicleData *__internal_ret = (Gitsn_DetectedVehicleData *)Dz1Calloc(sizeof(Gitsn_DetectedVehicleData), 1, errp);
	if (__internal_ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_DetectedVehicleData_delAndSetNull, (void *)&__internal_ret);
		
		ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_DetectedVehicleData_delAndSetNull, (void *)&__internal_ret)
	}
	return __internal_ret;
}

bool_t Gitsn_DetectedVehicleData_copy(Gitsn_DetectedVehicleData *dst, Gitsn_DetectedVehicleData *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->lights && (dst->lights = Gitsn_ExteriorLights_clone(src->lights, errp)) == NULL) ERR_OUT(errp);
	else if (src->vehAttitude && (dst->vehAttitude = Gitsn_Attitude_clone(src->vehAttitude, errp)) == NULL) ERR_OUT(errp);
	else if (src->vehAttitudeConfidence && (dst->vehAttitudeConfidence = Gitsn_AttitudeConfidence_clone(src->vehAttitudeConfidence, errp)) == NULL) ERR_OUT(errp);
	else if (src->vehAngVel && (dst->vehAngVel = Gitsn_AngularVelocity_clone(src->vehAngVel, errp)) == NULL) ERR_OUT(errp);
	else if (src->vehAngleConfidence && (dst->vehAngleConfidence = Gitsn_AngularVelocityConfidence_clone(src->vehAngleConfidence, errp)) == NULL) ERR_OUT(errp);
	else if (src->size && (dst->size = Gitsn_VehicleSize_clone(src->size, errp)) == NULL) ERR_OUT(errp);
	else if (src->vehicleSizeConfidence && (dst->vehicleSizeConfidence = Gitsn_VehicleSizeConfidence_clone(src->vehicleSizeConfidence, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->height = src->height;
		dst->vehicleClass = src->vehicleClass;
		dst->classConf = src->classConf;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_DetectedVehicleData *Gitsn_DetectedVehicleData_clone(Gitsn_DetectedVehicleData *src, Dz1Error *err)
{
	Gitsn_DetectedVehicleData *dst = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if ((dst = (Gitsn_DetectedVehicleData *)Dz1Calloc(sizeof(Gitsn_DetectedVehicleData), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_DetectedVehicleData_delAndSetNull, (void *)&dst);
		if (Gitsn_DetectedVehicleData_copy(dst, src, errp) == FALSE) ERR_SET_OUT(errp, EINVAL);
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_DetectedVehicleData_delAndSetNull, (void *)&dst);
	}
	return dst;
}

void Gitsn_DetectedVehicleData_purge(Gitsn_DetectedVehicleData *p)
{
	if (p == NULL) return;
	Gitsn_ExteriorLights_del(p->lights);
	Gitsn_Attitude_del(p->vehAttitude);
	Gitsn_AttitudeConfidence_del(p->vehAttitudeConfidence);
	Gitsn_AngularVelocity_del(p->vehAngVel);
	Gitsn_AngularVelocityConfidence_del(p->vehAngleConfidence);
	Gitsn_VehicleSize_del(p->size);
	Gitsn_VehicleSizeConfidence_del(p->vehicleSizeConfidence);
}

void Gitsn_DetectedVehicleData_del(Gitsn_DetectedVehicleData *p)
{
	if (p == NULL) return;
	Gitsn_DetectedVehicleData_purge(p);
	Dz1Free(p);
}

void Gitsn_DetectedVehicleData_dump(Gitsn_DetectedVehicleData *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else
	{
		Dz1Thread_printf(Dz1T("{\n")); tab++;
		Dz1Thread_tprintf(tab, Dz1T("lights = ")); Gitsn_ExteriorLights_dump(p->lights, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("vehAttitude = ")); Gitsn_Attitude_dump(p->vehAttitude, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("vehAttitudeConfidence = ")); Gitsn_AttitudeConfidence_dump(p->vehAttitudeConfidence, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("vehAngVel = ")); Gitsn_AngularVelocity_dump(p->vehAngVel, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("vehAngleConfidence = ")); Gitsn_AngularVelocityConfidence_dump(p->vehAngleConfidence, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("size = ")); Gitsn_VehicleSize_dump(p->size, tab); 
		Dz1Thread_tprintf(tab, Dz1T("height = ")); Gitsn_VehicleHeight_dump(&p->height, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("vehicleSizeConfidence = ")); Gitsn_VehicleSizeConfidence_dump(p->vehicleSizeConfidence, tab); 
		Dz1Thread_tprintf(tab, Dz1T("vehicleClass = ")); Gitsn_BasicVehicleClass_dump(&p->vehicleClass, tab); 
		Dz1Thread_tprintf(tab, Dz1T("classConf = ")); Gitsn_ClassificationConfidence_dump(&p->classConf, tab); 
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
	}
}
