////////////////////////////////////////////////////////////////////////////////
// Gitsn_PropelledInformation
Gitsn_PropelledInformation *Gitsn_PropelledInformation_new(Gitsn_PropelledInformationPresent present, void *ptr, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_PropelledInformation *ret = (Gitsn_PropelledInformation *)Dz1Calloc(sizeof(Gitsn_PropelledInformation), 1, errp);
	if (ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_PropelledInformation_delAndSetNull, (void *)&ret);

		ret->present = present;
		switch(ret->present)
		{
		case Gitsn_PropelledInformationPresent_human:
			// _U_enum_clone
			if (ptr != NULL) ret->x.human = *(Gitsn_HumanPropelledType *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_PropelledInformationPresent_animal:
			// _U_enum_clone
			if (ptr != NULL) ret->x.animal = *(Gitsn_AnimalPropelledType *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_PropelledInformationPresent_motor:
			// _U_enum_clone
			if (ptr != NULL) ret->x.motor = *(Gitsn_MotorizedPropelledType *)ptr;
			ERR_CLEAR(errp);
			break;
		case Gitsn_PropelledInformationPresent_max:
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_PropelledInformation_delAndSetNull, (void *)&ret);
	}
	return ret;
}

bool_t Gitsn_PropelledInformation_copy(Gitsn_PropelledInformation *ret, Gitsn_PropelledInformation *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL || ret == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else
	{
		ret->present = src->present;
		switch(src->present)
		{
		case Gitsn_PropelledInformationPresent_human:
			// _U_enum_clone
			ret->x.human = src->x.human;
			ERR_CLEAR(errp);
			break;
		case Gitsn_PropelledInformationPresent_animal:
			// _U_enum_clone
			ret->x.animal = src->x.animal;
			ERR_CLEAR(errp);
			break;
		case Gitsn_PropelledInformationPresent_motor:
			// _U_enum_clone
			ret->x.motor = src->x.motor;
			ERR_CLEAR(errp);
			break;
		default:
			ERR_SET_OUT(errp, EINVAL);
			break;
		}
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_PropelledInformation *Gitsn_PropelledInformation_clone(Gitsn_PropelledInformation *src, Dz1Error *err)
{
	Gitsn_PropelledInformation *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (Gitsn_PropelledInformation *)Dz1Calloc(sizeof(Gitsn_PropelledInformation), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_PropelledInformation_delAndSetNull, (void *)&ret);
		if (Gitsn_PropelledInformation_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_PropelledInformation_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_PropelledInformation_purge(Gitsn_PropelledInformation *p)
{
	if (!p) return;
	switch(p->present)
	{
	case Gitsn_PropelledInformationPresent_human:
		break;
	case Gitsn_PropelledInformationPresent_animal:
		break;
	case Gitsn_PropelledInformationPresent_motor:
		break;
	default:
		break;
	}
}

void Gitsn_PropelledInformation_del(Gitsn_PropelledInformation *p)
{
	if (!p) return;
	Gitsn_PropelledInformation_purge(p);
	Dz1Free(p);
}

void Gitsn_PropelledInformation_dump(Gitsn_PropelledInformation *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else switch(p->present)
	{
	case Gitsn_PropelledInformationPresent_human:
		Dz1Thread_printf(Dz1T("human = %s(%d)\n"), Gitsn_HumanPropelledTypeStr(p->x.human), p->x.human);
		break;
	case Gitsn_PropelledInformationPresent_animal:
		Dz1Thread_printf(Dz1T("animal = %s(%d)\n"), Gitsn_AnimalPropelledTypeStr(p->x.animal), p->x.animal);
		break;
	case Gitsn_PropelledInformationPresent_motor:
		Dz1Thread_printf(Dz1T("motor = %s(%d)\n"), Gitsn_MotorizedPropelledTypeStr(p->x.motor), p->x.motor);
		break;
	default:
		Dz1Thread_tprintf(tab, Dz1T("??? = %d\n"), p->present);
		break;
	}
}

