		Dz1Thread_tprintf(tab, Dz1T("vehicleType = %s(%d)\n"), Gitsn_VehicleGroupAffectedStr(p->vehicleType), p->vehicleType);
		Dz1Thread_tprintf(tab, Dz1T("responseEquip = %s(%d)\n"), Gitsn_IncidentResponseEquipmentStr(p->responseEquip), p->responseEquip);
		Dz1Thread_tprintf(tab, Dz1T("responderType = %s(%d)\n"), Gitsn_ResponderGroupAffectedStr(p->responderType), p->responderType);
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
