// Gitsn_RTCMmessageList
static Dz1Error Gitsn_RTCMmessageList_add(Gitsn_RTCMmessageList *p, Gitsn_RTCMmessage data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	err = Dz1Fifo_push(p->storage, data);
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

static Gitsn_RTCMmessage Gitsn_RTCMmessageList_extract(Gitsn_RTCMmessageList *p, Gitsn_RTCMmessage ptr)
{
	return (Gitsn_RTCMmessage )Dz1Fifo_extract(p->storage, ptr);
}

typedef struct Gitsn_RTCMmessageListMkArrArg
{
	Gitsn_RTCMmessage *arr;
	unsigned int idx;
} Gitsn_RTCMmessageListMkArrArg;

static Dz1Error _Gitsn_RTCMmessageList_get_array(void *ptr, Gitsn_RTCMmessage p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_RTCMmessageListMkArrArg *arg = (Gitsn_RTCMmessageListMkArrArg *)ptr;
	arg->arr[arg->idx++] = p;
	return err;
}

static Gitsn_RTCMmessage *Gitsn_RTCMmessageList_get_array(Gitsn_RTCMmessageList *p, unsigned int *ret_cnt, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err == NULL ? &_err : err;
	Gitsn_RTCMmessage *ret = NULL;
	unsigned int cnt = 0;
	if (p == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = (Gitsn_RTCMmessage *)Dz1Calloc(sizeof(Gitsn_RTCMmessage *), (cnt = p->count(p)) + 1, errp)) == NULL) ERR_OUT(errp);
	else
	{
		Gitsn_RTCMmessageListMkArrArg arg = { ret, 0 };
		pthread_cleanup_push(Dz1Memory_cancel, (void *)ret);

		*errp = p->travel(p, _Gitsn_RTCMmessageList_get_array, (void *)&arg);
		if (ERR_PROBE(errp)) ERR_OUT(errp);
		else
		{
			if (ret_cnt) (*ret_cnt) = cnt;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Dz1Memory_cancel, (void *)ret);
	}
	if (ERR_PROBE(errp)) ret = NULL;
	return ret;
}

static Dz1Error Gitsn_RTCMmessageList_travelForward(Gitsn_RTCMmessageList *p, Dz1Error (*func)(void *ptr, Gitsn_RTCMmessage data), void *ptr)
{
	return Dz1Fifo_travelForward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Dz1Error Gitsn_RTCMmessageList_travelBackward(Gitsn_RTCMmessageList *p, Dz1Error (*func)(void *ptr, Gitsn_RTCMmessage data), void *ptr)
{
	return Dz1Fifo_travelBackward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Gitsn_RTCMmessage Gitsn_RTCMmessageList_getHead(Gitsn_RTCMmessageList *p)
{
	return (Gitsn_RTCMmessage )Dz1Fifo_getFirst(p->storage);
}

static unsigned int Gitsn_RTCMmessageList_count(Gitsn_RTCMmessageList *p)
{
	unsigned int ret = Dz1Fifo_count(p->storage);
	return ret;
}

Gitsn_RTCMmessageList *Gitsn_RTCMmessageList_new(Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_RTCMmessageList *ret = (Gitsn_RTCMmessageList *)Dz1Calloc(sizeof(Gitsn_RTCMmessageList), 1, errp);
	if (ret == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_RTCMmessageList_delAndSetNull, (void *)&ret);

		if ((ret->storage = Dz1Fifo_newDynamic(
				(Dz1DelFunc)Gitsn_RTCMmessage_del,
				NULL, errp)) == NULL) ERR_OUT(errp);
		else
		{
			ret->count = Gitsn_RTCMmessageList_count;
			ret->travel = Gitsn_RTCMmessageList_travelForward;
			ret->travelForward = Gitsn_RTCMmessageList_travelForward;
			ret->travelBackward = Gitsn_RTCMmessageList_travelBackward;
			ret->get_array = Gitsn_RTCMmessageList_get_array;
			ret->add = Gitsn_RTCMmessageList_add;
			ret->extract = Gitsn_RTCMmessageList_extract;
			ret->getHead = Gitsn_RTCMmessageList_getHead;
			ret->cmp = Gitsn_RTCMmessage_cmp;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_RTCMmessageList_delAndSetNull, (void *)&ret);
	}
	return ret;
}

static Dz1Error _Gitsn_RTCMmessageList_clone(void *ptr, Gitsn_RTCMmessage data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_RTCMmessageList *p = (Gitsn_RTCMmessageList *)ptr;
	Gitsn_RTCMmessage cloned = Gitsn_RTCMmessage_clone(data, &err); // normal
	err = Dz1Fifo_push(p->storage, cloned); // chk
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

Gitsn_RTCMmessageList *Gitsn_RTCMmessageList_clone(Gitsn_RTCMmessageList *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_RTCMmessageList *ret = NULL;
	if (src == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = Gitsn_RTCMmessageList_new(errp)) == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_RTCMmessageList_delAndSetNull, (void *)&ret);

		*errp = Dz1Fifo_travelForward(src->storage, (Dz1FifoTravelFunc)_Gitsn_RTCMmessageList_clone, (void *)ret);

		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_RTCMmessageList_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void Gitsn_RTCMmessageList_purge(Gitsn_RTCMmessageList *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_empty(p->storage);
}

void Gitsn_RTCMmessageList_del(Gitsn_RTCMmessageList *p)
{
	if (!p) return;
	if (p->storage) Dz1Fifo_del(p->storage);
	Dz1Free(p);
}

