// Gitsn_RTCMcorrections
Gitsn_RTCMcorrections *Gitsn_RTCMcorrections_new(Gitsn_MsgCount msgCnt, 
												 Gitsn_RTCM_Revision rev, 
												 Gitsn_RTCMmessageList *msgs, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_RTCMcorrections *__internal_ret = (Gitsn_RTCMcorrections *)Dz1Calloc(sizeof(Gitsn_RTCMcorrections), 1, errp);
	if (__internal_ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_RTCMcorrections_delAndSetNull, (void *)&__internal_ret);
		
		__internal_ret->msgCnt = msgCnt;
		__internal_ret->rev = rev;
		__internal_ret->msgs = msgs;
		ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_RTCMcorrections_delAndSetNull, (void *)&__internal_ret)
	}
	return __internal_ret;
}

bool_t Gitsn_RTCMcorrections_copy(Gitsn_RTCMcorrections *dst, Gitsn_RTCMcorrections *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->anchorPoint && (dst->anchorPoint = Gitsn_FullPositionVector_clone(src->anchorPoint, errp)) == NULL) ERR_OUT(errp);
	else if (src->rtcmHeader && (dst->rtcmHeader = Gitsn_RTCMheader_clone(src->rtcmHeader, errp)) == NULL) ERR_OUT(errp);
	else if (src->msgs && (dst->msgs = Gitsn_RTCMmessageList_clone(src->msgs, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->msgCnt = src->msgCnt;
		dst->rev = src->rev;
		dst->timeStamp = src->timeStamp;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_RTCMcorrections *Gitsn_RTCMcorrections_clone(Gitsn_RTCMcorrections *src, Dz1Error *err)
{
	Gitsn_RTCMcorrections *dst = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if ((dst = (Gitsn_RTCMcorrections *)Dz1Calloc(sizeof(Gitsn_RTCMcorrections), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_RTCMcorrections_delAndSetNull, (void *)&dst);
		if (Gitsn_RTCMcorrections_copy(dst, src, errp) == FALSE) ERR_SET_OUT(errp, EINVAL);
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_RTCMcorrections_delAndSetNull, (void *)&dst);
	}
	return dst;
}

void Gitsn_RTCMcorrections_purge(Gitsn_RTCMcorrections *p)
{
	if (p == NULL) return;
	Gitsn_FullPositionVector_del(p->anchorPoint);
	Gitsn_RTCMheader_del(p->rtcmHeader);
	Gitsn_RTCMmessageList_del(p->msgs);
}

void Gitsn_RTCMcorrections_del(Gitsn_RTCMcorrections *p)
{
	if (p == NULL) return;
	Gitsn_RTCMcorrections_purge(p);
	Dz1Free(p);
}

void Gitsn_RTCMcorrections_dump(Gitsn_RTCMcorrections *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else
	{
		Dz1Thread_printf(Dz1T("{\n")); tab++;
		Dz1Thread_tprintf(tab, Dz1T("msgCnt = ")); Gitsn_MsgCount_dump(&p->msgCnt, tab); 
		Dz1Thread_tprintf(tab, Dz1T("rev = %s(%d)\n"), Gitsn_RTCM_RevisionStr(p->rev), p->rev);
		Dz1Thread_tprintf(tab, Dz1T("timeStamp = ")); Gitsn_MinuteOfTheYear_dump(&p->timeStamp, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("anchorPoint = ")); Gitsn_FullPositionVector_dump(p->anchorPoint, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("rtcmHeader = ")); Gitsn_RTCMheader_dump(p->rtcmHeader, tab); 
		Dz1Thread_tprintf(tab, Dz1T("msgs = ")); Gitsn_RTCMmessageList_dump(p->msgs, tab); 
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
	}
}
