{
	if (p == NULL) return;
	Gitsn_IntersectionReferenceID_del(p->id);
	Gitsn_IntersectionAccessPoint_del(p->inBoundLane);
	Gitsn_IntersectionAccessPoint_del(p->outBoundLane);
}

