		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("id = ")); Gitsn_IntersectionReferenceID_dump(p->id, tab); 
		Dz1Thread_tprintf(tab, Dz1T("requestID = ")); Gitsn_RequestID_dump(&p->requestID, tab); 
		Dz1Thread_tprintf(tab, Dz1T("requestType = %s(%d)\n"), Gitsn_PriorityRequestTypeStr(p->requestType), p->requestType);
		Dz1Thread_tprintf(tab, Dz1T("inBoundLane.")); Gitsn_IntersectionAccessPoint_dump(p->inBoundLane, tab); 
		Dz1Thread_tprintf(tab, Dz1T("outBoundLane.")); Gitsn_IntersectionAccessPoint_dump(p->outBoundLane, tab); 
