// Gitsn_SignalStatusPackageList
static Dz1Error Gitsn_SignalStatusPackageList_add(Gitsn_SignalStatusPackageList *p, Gitsn_SignalStatusPackage *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	err = Dz1Fifo_push(p->storage, data);
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

static Gitsn_SignalStatusPackage *Gitsn_SignalStatusPackageList_extract(Gitsn_SignalStatusPackageList *p, Gitsn_SignalStatusPackage *ptr)
{
	return (Gitsn_SignalStatusPackage *)Dz1Fifo_extract(p->storage, ptr);
}

typedef struct Gitsn_SignalStatusPackageListMkArrArg
{
	Gitsn_SignalStatusPackage **arr;
	unsigned int idx;
} Gitsn_SignalStatusPackageListMkArrArg;

static Dz1Error _Gitsn_SignalStatusPackageList_get_array(void *ptr, Gitsn_SignalStatusPackage *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_SignalStatusPackageListMkArrArg *arg = (Gitsn_SignalStatusPackageListMkArrArg *)ptr;
	arg->arr[arg->idx++] = p;
	return err;
}

static Gitsn_SignalStatusPackage **Gitsn_SignalStatusPackageList_get_array(Gitsn_SignalStatusPackageList *p, unsigned int *ret_cnt, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err == NULL ? &_err : err;
	Gitsn_SignalStatusPackage **ret = NULL;
	unsigned int cnt = 0;
	if (p == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = (Gitsn_SignalStatusPackage **)Dz1Calloc(sizeof(Gitsn_SignalStatusPackage *), (cnt = p->count(p)) + 1, errp)) == NULL) ERR_OUT(errp);
	else
	{
		Gitsn_SignalStatusPackageListMkArrArg arg = { ret, 0 };
		pthread_cleanup_push(Dz1Memory_cancel, (void *)ret);

		*errp = p->travel(p, _Gitsn_SignalStatusPackageList_get_array, (void *)&arg);
		if (ERR_PROBE(errp)) ERR_OUT(errp);
		else
		{
			if (ret_cnt) (*ret_cnt) = cnt;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Dz1Memory_cancel, (void *)ret);
	}
	if (ERR_PROBE(errp)) ret = NULL;
	return ret;
}

static Dz1Error Gitsn_SignalStatusPackageList_travelForward(Gitsn_SignalStatusPackageList *p, Dz1Error (*func)(void *ptr, Gitsn_SignalStatusPackage *data), void *ptr)
{
	return Dz1Fifo_travelForward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Dz1Error Gitsn_SignalStatusPackageList_travelBackward(Gitsn_SignalStatusPackageList *p, Dz1Error (*func)(void *ptr, Gitsn_SignalStatusPackage *data), void *ptr)
{
	return Dz1Fifo_travelBackward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Gitsn_SignalStatusPackage *Gitsn_SignalStatusPackageList_getHead(Gitsn_SignalStatusPackageList *p)
{
	return (Gitsn_SignalStatusPackage *)Dz1Fifo_getFirst(p->storage);
}

static unsigned int Gitsn_SignalStatusPackageList_count(Gitsn_SignalStatusPackageList *p)
{
	unsigned int ret = Dz1Fifo_count(p->storage);
	return ret;
}

Gitsn_SignalStatusPackageList *Gitsn_SignalStatusPackageList_new(Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_SignalStatusPackageList *ret = (Gitsn_SignalStatusPackageList *)Dz1Calloc(sizeof(Gitsn_SignalStatusPackageList), 1, errp);
	if (ret == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_SignalStatusPackageList_delAndSetNull, (void *)&ret);

		if ((ret->storage = Dz1Fifo_newDynamic(
				(Dz1DelFunc)Gitsn_SignalStatusPackage_del,
				NULL, errp)) == NULL) ERR_OUT(errp);
		else
		{
			ret->count = Gitsn_SignalStatusPackageList_count;
			ret->travel = Gitsn_SignalStatusPackageList_travelForward;
			ret->travelForward = Gitsn_SignalStatusPackageList_travelForward;
			ret->travelBackward = Gitsn_SignalStatusPackageList_travelBackward;
			ret->get_array = Gitsn_SignalStatusPackageList_get_array;
			ret->add = Gitsn_SignalStatusPackageList_add;
			ret->extract = Gitsn_SignalStatusPackageList_extract;
			ret->getHead = Gitsn_SignalStatusPackageList_getHead;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_SignalStatusPackageList_delAndSetNull, (void *)&ret);
	}
	return ret;
}

static Dz1Error _Gitsn_SignalStatusPackageList_clone(void *ptr, Gitsn_SignalStatusPackage *data)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_SignalStatusPackageList *p = (Gitsn_SignalStatusPackageList *)ptr;
	Gitsn_SignalStatusPackage *cloned = Gitsn_SignalStatusPackage_clone(data, &err); // normal
	err = Dz1Fifo_push(p->storage, cloned); // chk
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

