{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	err = Dz1Fifo_push(p->storage, data);
	if (ERR_PROBE(&err)) ERR_OUT(&err);
	return err;
}

static Gitsn_SignalStatus *Gitsn_SignalStatusList_extract(Gitsn_SignalStatusList *p, Gitsn_SignalStatus *ptr)
{
	return (Gitsn_SignalStatus *)Dz1Fifo_extract(p->storage, ptr);
}

typedef struct Gitsn_SignalStatusListMkArrArg
{
	Gitsn_SignalStatus **arr;
	unsigned int idx;
} Gitsn_SignalStatusListMkArrArg;

static Dz1Error _Gitsn_SignalStatusList_get_array(void *ptr, Gitsn_SignalStatus *p)
{
	Dz1Error err = DZ1_ERROR_INITIALIZER;
	Gitsn_SignalStatusListMkArrArg *arg = (Gitsn_SignalStatusListMkArrArg *)ptr;
	arg->arr[arg->idx++] = p;
	return err;
}

static Gitsn_SignalStatus **Gitsn_SignalStatusList_get_array(Gitsn_SignalStatusList *p, unsigned int *ret_cnt, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err == NULL ? &_err : err;
	Gitsn_SignalStatus **ret = NULL;
	unsigned int cnt = 0;
	if (p == NULL) ERR_SET_OUT(errp, EINVAL);
	else if ((ret = (Gitsn_SignalStatus **)Dz1Calloc(sizeof(Gitsn_SignalStatus *), (cnt = p->count(p)) + 1, errp)) == NULL) ERR_OUT(errp);
	else
	{
		Gitsn_SignalStatusListMkArrArg arg = { ret, 0 };
		pthread_cleanup_push(Dz1Memory_cancel, (void *)ret);

		*errp = p->travel(p, _Gitsn_SignalStatusList_get_array, (void *)&arg);
		if (ERR_PROBE(errp)) ERR_OUT(errp);
		else
		{
			if (ret_cnt) (*ret_cnt) = cnt;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Dz1Memory_cancel, (void *)ret);
	}
	if (ERR_PROBE(errp)) ret = NULL;
	return ret;
}

static Dz1Error Gitsn_SignalStatusList_travelForward(Gitsn_SignalStatusList *p, Dz1Error (*func)(void *ptr, Gitsn_SignalStatus *data), void *ptr)
{
	return Dz1Fifo_travelForward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

static Dz1Error Gitsn_SignalStatusList_travelBackward(Gitsn_SignalStatusList *p, Dz1Error (*func)(void *ptr, Gitsn_SignalStatus *data), void *ptr)
{
	return Dz1Fifo_travelBackward(p->storage, (Dz1FifoTravelFunc)func, ptr);
}

