{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_SignalStatusList *ret = (Gitsn_SignalStatusList *)Dz1Calloc(sizeof(Gitsn_SignalStatusList), 1, errp);
	if (ret == NULL) ERR_OUT(errp);
	else
	{
		pthread_cleanup_push(Gitsn_SignalStatusList_delAndSetNull, (void *)&ret);

		if ((ret->storage = Dz1Fifo_newDynamic(
				(Dz1DelFunc)Gitsn_SignalStatus_del,
				NULL, errp)) == NULL) ERR_OUT(errp);
		else
		{
			ret->count = Gitsn_SignalStatusList_count;
			ret->travel = Gitsn_SignalStatusList_travelForward;
			ret->travelForward = Gitsn_SignalStatusList_travelForward;
			ret->travelBackward = Gitsn_SignalStatusList_travelBackward;
			ret->get_array = Gitsn_SignalStatusList_get_array;
			ret->add = Gitsn_SignalStatusList_add;
			ret->extract = Gitsn_SignalStatusList_extract;
			ret->getHead = Gitsn_SignalStatusList_getHead;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_SignalStatusList_delAndSetNull, (void *)&ret);
	}
	return ret;
}

