// Gitsn_PersonalSafetyMessage
Gitsn_PersonalSafetyMessage *Gitsn_PersonalSafetyMessage_new(Gitsn_PersonalDeviceUserType basicType, 
															 Gitsn_DSecond secMark, 
															 Gitsn_MsgCount msgCnt, 
															 Gitsn_TemporaryID id, 
															 Gitsn_Position3D *position, 
															 Gitsn_PositionalAccuracy *accuracy, 
															 Gitsn_Velocity speed, 
															 Gitsn_Heading heading, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	Gitsn_PersonalSafetyMessage *__internal_ret = (Gitsn_PersonalSafetyMessage *)Dz1Calloc(sizeof(Gitsn_PersonalSafetyMessage), 1, errp);
	if (__internal_ret == NULL) { ERR_SET_OUT(errp, ENOMEM); }
	else
	{
		pthread_cleanup_push(Gitsn_PersonalSafetyMessage_delAndSetNull, (void *)&__internal_ret);
		
		if (id && (__internal_ret->id = Gitsn_TemporaryID_clone(id, errp)) == NULL) ERR_OUT(errp);
		else
		{
			__internal_ret->basicType = basicType;
			__internal_ret->secMark = secMark;
			__internal_ret->msgCnt = msgCnt;
			__internal_ret->position = position;
			__internal_ret->accuracy = accuracy;
			__internal_ret->speed = speed;
			__internal_ret->heading = heading;
			ERR_CLEAR(errp);
		}
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_PersonalSafetyMessage_delAndSetNull, (void *)&__internal_ret)
	}
	return __internal_ret;
}

bool_t Gitsn_PersonalSafetyMessage_copy(Gitsn_PersonalSafetyMessage *dst, Gitsn_PersonalSafetyMessage *src, Dz1Error *err)
{
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (dst == NULL || src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if (src->id && (dst->id = Gitsn_TemporaryID_clone(src->id, errp)) == NULL) ERR_OUT(errp);
	else if (src->position && (dst->position = Gitsn_Position3D_clone(src->position, errp)) == NULL) ERR_OUT(errp);
	else if (src->accuracy && (dst->accuracy = Gitsn_PositionalAccuracy_clone(src->accuracy, errp)) == NULL) ERR_OUT(errp);
	else if (src->accelSet && (dst->accelSet = Gitsn_AccelerationSet4Way_clone(src->accelSet, errp)) == NULL) ERR_OUT(errp);
	else if (src->pathHistory && (dst->pathHistory = Gitsn_PathHistory_clone(src->pathHistory, errp)) == NULL) ERR_OUT(errp);
	else if (src->pathPrediction && (dst->pathPrediction = Gitsn_PathPrediction_clone(src->pathPrediction, errp)) == NULL) ERR_OUT(errp);
	else if (src->propulsion && (dst->propulsion = Gitsn_PropelledInformation_clone(src->propulsion, errp)) == NULL) ERR_OUT(errp);
	else if (src->useState && (dst->useState = Gitsn_PersonalDeviceUsageState_clone(src->useState, errp)) == NULL) ERR_OUT(errp);
	else if (src->activityType && (dst->activityType = Gitsn_PublicSafetyAndRoadWorkerActivity_clone(src->activityType, errp)) == NULL) ERR_OUT(errp);
	else if (src->activitySubType && (dst->activitySubType = Gitsn_PublicSafetyDirectingTrafficSubType_clone(src->activitySubType, errp)) == NULL) ERR_OUT(errp);
	else if (src->assistType && (dst->assistType = Gitsn_PersonalAssistive_clone(src->assistType, errp)) == NULL) ERR_OUT(errp);
	else if (src->sizing && (dst->sizing = Gitsn_UserSizeAndBehaviour_clone(src->sizing, errp)) == NULL) ERR_OUT(errp);
	else
	{
		dst->basicType = src->basicType;
		dst->secMark = src->secMark;
		dst->msgCnt = src->msgCnt;
		dst->speed = src->speed;
		dst->heading = src->heading;
		dst->crossRequest = src->crossRequest;
		dst->crossState = src->crossState;
		dst->clusterSize = src->clusterSize;
		dst->clusterRadius = src->clusterRadius;
		dst->eventResponderType = src->eventResponderType;
		dst->attachment = src->attachment;
		dst->attachmentRadius = src->attachmentRadius;
		dst->animalType = src->animalType;
		ERR_CLEAR(errp);
	}
	return ERR_PROBE(errp) ? FALSE : TRUE;
}

Gitsn_PersonalSafetyMessage *Gitsn_PersonalSafetyMessage_clone(Gitsn_PersonalSafetyMessage *src, Dz1Error *err)
{
	Gitsn_PersonalSafetyMessage *dst = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { ERR_SET_OUT(errp, EINVAL); }
	else if ((dst = (Gitsn_PersonalSafetyMessage *)Dz1Calloc(sizeof(Gitsn_PersonalSafetyMessage), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(Gitsn_PersonalSafetyMessage_delAndSetNull, (void *)&dst);
		if (Gitsn_PersonalSafetyMessage_copy(dst, src, errp) == FALSE) ERR_SET_OUT(errp, EINVAL);
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (Gitsn_PersonalSafetyMessage_delAndSetNull, (void *)&dst);
	}
	return dst;
}

void Gitsn_PersonalSafetyMessage_purge(Gitsn_PersonalSafetyMessage *p)
{
	if (p == NULL) return;
	Gitsn_TemporaryID_del(p->id);
	Gitsn_Position3D_del(p->position);
	Gitsn_PositionalAccuracy_del(p->accuracy);
	Gitsn_AccelerationSet4Way_del(p->accelSet);
	Gitsn_PathHistory_del(p->pathHistory);
	Gitsn_PathPrediction_del(p->pathPrediction);
	Gitsn_PropelledInformation_del(p->propulsion);
	Gitsn_PersonalDeviceUsageState_del(p->useState);
	Gitsn_PublicSafetyAndRoadWorkerActivity_del(p->activityType);
	Gitsn_PublicSafetyDirectingTrafficSubType_del(p->activitySubType);
	Gitsn_PersonalAssistive_del(p->assistType);
	Gitsn_UserSizeAndBehaviour_del(p->sizing);
}

void Gitsn_PersonalSafetyMessage_del(Gitsn_PersonalSafetyMessage *p)
{
	if (p == NULL) return;
	Gitsn_PersonalSafetyMessage_purge(p);
	Dz1Free(p);
}

void Gitsn_PersonalSafetyMessage_dump(Gitsn_PersonalSafetyMessage *p, int tab)
{
	if (!p) Dz1Thread_printf(Dz1T("NULL\n"));
	else
	{
		Dz1Thread_printf(Dz1T("{\n")); tab++;
		Dz1Thread_tprintf(tab, Dz1T("basicType = %s(%d)\n"), Gitsn_PersonalDeviceUserTypeStr(p->basicType), p->basicType);
		Dz1Thread_tprintf(tab, Dz1T("secMark = ")); Gitsn_DSecond_dump(&p->secMark, tab); 
		Dz1Thread_tprintf(tab, Dz1T("msgCnt = ")); Gitsn_MsgCount_dump(&p->msgCnt, tab); 
		Dz1Thread_tprintf(tab, Dz1T("id = ")); Gitsn_TemporaryID_dump(p->id, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("position = ")); Gitsn_Position3D_dump(p->position, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("accuracy = ")); Gitsn_PositionalAccuracy_dump(p->accuracy, tab); 
		Dz1Thread_tprintf(tab, Dz1T("speed = ")); Gitsn_Velocity_dump(&p->speed, tab); 
		Dz1Thread_tprintf(tab, Dz1T("heading = ")); Gitsn_Heading_dump(&p->heading, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("accelSet = ")); Gitsn_AccelerationSet4Way_dump(p->accelSet, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("pathHistory = ")); Gitsn_PathHistory_dump(p->pathHistory, tab); 
		// Normal member
		Dz1Thread_tprintf(tab, Dz1T("pathPrediction = ")); Gitsn_PathPrediction_dump(p->pathPrediction, tab); 
		Dz1Thread_tprintf(tab, Dz1T("propulsion.")); Gitsn_PropelledInformation_dump(p->propulsion, tab); 
		Dz1Thread_tprintf(tab, Dz1T("useState = ")); Gitsn_PersonalDeviceUsageState_dump(p->useState, tab); 
		Dz1Thread_tprintf(tab, Dz1T("crossRequest = ")); Gitsn_PersonalCrossingRequest_dump(&p->crossRequest, tab); 
		Dz1Thread_tprintf(tab, Dz1T("crossState = ")); Gitsn_PersonalCrossingInProgress_dump(&p->crossState, tab); 
		Dz1Thread_tprintf(tab, Dz1T("clusterSize = %s(%d)\n"), Gitsn_NumberOfParticipantsInClusterStr(p->clusterSize), p->clusterSize);
		Dz1Thread_tprintf(tab, Dz1T("clusterRadius = ")); Gitsn_PersonalClusterRadius_dump(&p->clusterRadius, tab); 
		Dz1Thread_tprintf(tab, Dz1T("eventResponderType = %s(%d)\n"), Gitsn_PublicSafetyEventResponderWorkerTypeStr(p->eventResponderType), p->eventResponderType);
		Dz1Thread_tprintf(tab, Dz1T("activityType = ")); Gitsn_PublicSafetyAndRoadWorkerActivity_dump(p->activityType, tab); 
		Dz1Thread_tprintf(tab, Dz1T("activitySubType = ")); Gitsn_PublicSafetyDirectingTrafficSubType_dump(p->activitySubType, tab); 
		Dz1Thread_tprintf(tab, Dz1T("assistType = ")); Gitsn_PersonalAssistive_dump(p->assistType, tab); 
		Dz1Thread_tprintf(tab, Dz1T("sizing = ")); Gitsn_UserSizeAndBehaviour_dump(p->sizing, tab); 
		Dz1Thread_tprintf(tab, Dz1T("attachment = %s(%d)\n"), Gitsn_AttachmentStr(p->attachment), p->attachment);
		Dz1Thread_tprintf(tab, Dz1T("attachmentRadius = ")); Gitsn_AttachmentRadius_dump(&p->attachmentRadius, tab); 
		Dz1Thread_tprintf(tab, Dz1T("animalType = %s(%d)\n"), Gitsn_AnimalTypeStr(p->animalType), p->animalType);
		Dz1Thread_tprintf(--tab, Dz1T("}\n"));
	}
}
