GitsnDSRCMsg *GitsnDSRCMsg_clone(GitsnDSRCMsg *src, Dz1Error *err)
{
	GitsnDSRCMsg *ret = NULL;
	Dz1Error _err = DZ1_ERROR_INITIALIZER, *errp = err ? err : &_err;
	if (src == NULL) { errp->code = EINVAL; ERR_OUT(errp); }
	else if ((ret = (GitsnDSRCMsg *)Dz1Calloc(sizeof(GitsnDSRCMsg), 1, errp)) == NULL) { ERR_OUT(errp); }
	else
	{
		pthread_cleanup_push(GitsnDSRCMsg_delAndSetNull, (void *)&ret);
		if (GitsnDSRCMsg_copy(ret, src, errp) == FALSE) { ERR_OUT(errp); }
		else ERR_CLEAR(errp);
		pthread_cleanup_pop(ERR_PROBE(errp)); // (GitsnDSRCMsg_delAndSetNull, (void *)&ret);
	}
	return ret;
}

void GitsnDSRCMsg_purge(GitsnDSRCMsg *p)
{
	if (!p) return;
	switch(p->present)
	{
	case GitsnDSRCMsgPresent_map:
		Gitsn_MapData_del(p->x.map);
		break;
	case GitsnDSRCMsgPresent_spat:
		Gitsn_SPAT_del(p->x.spat);
		break;
	case GitsnDSRCMsgPresent_bsm:
		Gitsn_BasicSafetyMessage_del(p->x.bsm);
		break;
	case GitsnDSRCMsgPresent_eva:
		Gitsn_EmergencyVehicleAlert_del(p->x.eva);
		break;
	case GitsnDSRCMsgPresent_pvd:
		Gitsn_ProbeVehicleData_del(p->x.pvd);
		break;
	case GitsnDSRCMsgPresent_rsa:
		Gitsn_RoadSideAlert_del(p->x.rsa);
		break;
	case GitsnDSRCMsgPresent_rtcm:
		Gitsn_RTCMcorrections_del(p->x.rtcm);
		break;
	case GitsnDSRCMsgPresent_srm:
		Gitsn_SignalRequestMessage_del(p->x.srm);
		break;
	case GitsnDSRCMsgPresent_ssm:
		Gitsn_SignalStatusMessage_del(p->x.ssm);
		break;
	case GitsnDSRCMsgPresent_tim:
		Gitsn_TravelerInformation_del(p->x.tim);
		break;
	case GitsnDSRCMsgPresent_psm:
		Gitsn_PersonalSafetyMessage_del(p->x.psm);
		break;
	case GitsnDSRCMsgPresent_sdsm:
		Gitsn_SensorDataSharingMessage_del(p->x.sdsm);
		break;
	case GitsnDSRCMsgPresent_tls:
		Gitsn_TLS_del(p->x.tls);
		break;
	case GitsnDSRCMsgPresent_tlsm:
		Gitsn_TrafficLightStatusMessage_del(p->x.tlsm);
		break;
	default:
		break;
	}
}

void GitsnDSRCMsg_del(GitsnDSRCMsg *p)
{
	if (!p) return;
	GitsnDSRCMsg_purge(p);
	Dz1Free(p);
}

